-- ====================================================================================================
-- 8/17  update_lobby_who.sql
-- ====================================================================================================
-- LAN Party 2: "who is online" list for the PondOS chat.
-- Run once in the Supabase SQL editor after update_open_chat.sql. Safe to run again.
--
-- Reads only: nothing new is stored. The chat already keeps games.lobby_seen (who has the chat open,
-- refreshed by gry_lobby_chat, deleted after 10 minutes). This function turns it into a list:
--   * frens: verified (Discord) players with the chat open in the last 90 seconds, by their reserved nickname;
--   * guests: nicknames of guests who wrote in the last 15 minutes (guests have no account to show as "online");
--   * lurkers: everyone else with the chat open, as a number only.
-- No IP hashes, Discord ids or visitor ids leave the database. user_id is returned for verified frens only,
-- because the chat messages already carry it (it opens the Fren Passport).

create or replace function public.gry_lobby_who(p_visitor text default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u uuid := auth.uid(); fr jsonb; gu jsonb; n_on int; n_fr int; n_gu int;
begin
  select count(*) into n_on from games.lobby_seen where seen_at > now() - interval '90 seconds';

  select coalesce(jsonb_agg(jsonb_build_object('user_id', x.user_id, 'nick', x.nick, 'me', x.user_id = u) order by lower(x.nick)), '[]'::jsonb), count(*)
    into fr, n_fr
    from (select distinct p.user_id, p.nick
            from games.lobby_seen s join games.profiles p on p.user_id = s.user_id
           where s.seen_at > now() - interval '90 seconds' and p.discord_id is not null
           limit 60) x;

  select coalesce(jsonb_agg(jsonb_build_object('nick', g.nick) order by g.last_at desc), '[]'::jsonb), count(*)
    into gu, n_gu
    from (select nick, max(created_at) last_at from games.lobby_chat
           where created_at > now() - interval '15 minutes' and hidden_at is null and not verified
           group by nick order by max(created_at) desc limit 30) g;

  return jsonb_build_object('frens', fr, 'guests', gu, 'lurkers', greatest(0, n_on - n_fr - n_gu));
end $$;

revoke all on function public.gry_lobby_who(text) from public;
grant execute on function public.gry_lobby_who(text) to anon, authenticated;

-- ====================================================================================================
-- 9/17  update_fren_passport.sql
-- ====================================================================================================
-- Fren Passport v1: private collections and read-only profile snapshot.
-- Apply to PH-games after games/supabase/schema.sql and update_yeet.sql.
-- This migration does NOT grant any badge, Moon Rock or secret to a user.
-- Future games must award collectibles through authenticated, server-validated actions.

create table if not exists games.passport_badges (
  user_id uuid not null references auth.users(id) on delete cascade,
  badge_id text not null check (badge_id ~ '^[a-z0-9_]{3,48}$'),
  earned_at timestamptz not null default clock_timestamp(),
  primary key (user_id, badge_id)
);
create table if not exists games.passport_secrets (
  user_id uuid not null references auth.users(id) on delete cascade,
  secret_id text not null check (secret_id ~ '^[a-z0-9_]{3,48}$'),
  discovered_at timestamptz not null default clock_timestamp(),
  primary key (user_id, secret_id)
);
create table if not exists games.passport_items (
  user_id uuid not null references auth.users(id) on delete cascade,
  item_id text not null check (item_id ~ '^[a-z0-9_]{3,48}$'),
  quantity integer not null default 1 check (quantity between 1 and 999),
  earned_at timestamptz not null default clock_timestamp(),
  primary key (user_id, item_id)
);

-- No public API access to collection tables. Their rows can only be read
-- through the identity-checked, read-only RPC below.
alter table games.passport_badges enable row level security;
alter table games.passport_secrets enable row level security;
alter table games.passport_items enable row level security;
revoke all on games.passport_badges from public, anon, authenticated;
revoke all on games.passport_secrets from public, anon, authenticated;
revoke all on games.passport_items from public, anon, authenticated;

create or replace function public.gry_passport_state()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
  d jsonb;
  joined timestamptz;
  best_distance integer := 0;
  best_date timestamptz;
  extra_badges jsonb;
  discovered jsonb;
  owned_items jsonb;
  earned_count integer;
  badge_catalog jsonb;
begin
  -- Anonymous Supabase users also have auth.uid(). Require Discord specifically.
  if u is null then
    return jsonb_build_object('signed_in', false);
  end if;
  d := games.discord_identity(u);
  if d is null then
    return jsonb_build_object('signed_in', false);
  end if;

  select au.created_at into joined
    from auth.users au where au.id = u;

  select coalesce(y.best, 0), y.achieved_at
    into best_distance, best_date
    from games.yeet_records y where y.user_id = u;
  best_distance := coalesce(best_distance, 0);

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', b.badge_id, 'title', b.badge_id,
           'description', 'Awarded by a PepecoinHub game',
           'earned_at', b.earned_at) order by b.earned_at), '[]'::jsonb)
    into extra_badges
    from games.passport_badges b where b.user_id = u and b.badge_id <> 'certified_fren';

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.secret_id, 'discovered_at', s.discovered_at)
           order by s.discovered_at), '[]'::jsonb)
    into discovered
    from games.passport_secrets s where s.user_id = u;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', i.item_id, 'quantity', i.quantity, 'earned_at', i.earned_at)
           order by i.earned_at), '[]'::jsonb)
    into owned_items
    from games.passport_items i where i.user_id = u;

  badge_catalog := jsonb_build_array(
    jsonb_build_object('id', 'first_fren', 'title', 'First Fren',
      'description', 'Joined the pond with Discord.', 'earned_at', joined),
    jsonb_build_object('id', 'moonwalker', 'title', 'Moonwalker',
      'description', 'Recorded a 6000 m YEET flight. Moon Rock inventory validation is not enabled yet.',
      'earned_at', case when best_distance = 60000 then best_date else null end),
    jsonb_build_object('id', 'certified_fren', 'title', 'Certified Fren',
      'description', '100 distinct care days in PepeGochi.',
      'earned_at', (select b.earned_at from games.passport_badges b
                    where b.user_id = u and b.badge_id = 'certified_fren'))
  );
  select count(*) into earned_count from jsonb_array_elements(badge_catalog) x
    where x->>'earned_at' is not null;
  earned_count := earned_count + jsonb_array_length(extra_badges);

  return jsonb_build_object(
    'signed_in', true,
    'nickname', coalesce(nullif(d->>'name', ''), 'Discord fren'),
    'member_since', joined,
    'yeet_best', best_distance,
    'achievements', badge_catalog || extra_badges,
    'achievements_earned', earned_count,
    'secrets', discovered,
    'items', owned_items,
    'care_days', null
  );
end
$$;

revoke all on function public.gry_passport_state() from public, anon, authenticated;
grant execute on function public.gry_passport_state() to authenticated;

-- Casual PondOS easter eggs. Only these small, cosmetic discoveries can be
-- claimed from the browser. Server-verifiable accomplishments (YEET, 100 care
-- days, limited badges and valuable inventory) must be awarded by their own
-- validated game code, never by this RPC.
create or replace function public.gry_passport_discover(p_secret text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
  d jsonb;
  new_discovery timestamptz;
  existing_discovery timestamptz;
begin
  if u is null then raise exception 'Log on with Discord to save secrets'; end if;
  d := games.discord_identity(u);
  if d is null then raise exception 'Log on with Discord to save secrets'; end if;
  -- happy_fren and born_to_fren are given by the chat trigger only (update_passport_awards.sql), never claimed here
  if p_secret is null or p_secret not in ('wrong_frog', 'why_tho', 'magic_word', 'bsod_fren', 'midnight_fren', 'nerd_alert', 'bali_dreamer',
      'find_fren', 'address_check') then
    raise exception 'Unknown discovery';
  end if;

  insert into games.passport_secrets(user_id, secret_id)
  values (u, p_secret)
  on conflict (user_id, secret_id) do nothing
  returning discovered_at into new_discovery;

  select s.discovered_at into existing_discovery
    from games.passport_secrets s
   where s.user_id = u and s.secret_id = p_secret;

  return jsonb_build_object(
    'id', p_secret,
    'new', new_discovery is not null,
    'discovered_at', existing_discovery
  );
end
$$;
revoke all on function public.gry_passport_discover(text) from public, anon, authenticated;
grant execute on function public.gry_passport_discover(text) to authenticated;

-- ====================================================================================================
-- 10/17  update_fren_avatar.sql
-- ====================================================================================================
-- Fren Avatar Maker v2: one saved Fren look per Discord player, and the
-- Fresh Fren achievement (first_avatar) for the first look the server saves.
-- DRAFT. Apply to PH-games only after review, after update_fren_passport.sql.
-- Safe to run twice. It awards nothing by itself.
--
-- v2 schema (Stage D): the avatar is a stack of 512x512 SVG layers described in
-- docs/meme/avatar-options.json (schema_version 2). layers_order is
-- [bg, base, clothing, mouth, eyes, hat, accessory]. 'base' (defaults.base =
-- 'base_frog') is a single implied constant layer painted between bg and
-- clothing; it is NOT a saved column. The saveable slots (columns) are:
-- bg, clothing, mouth, eyes, hat, accessory.
--
-- v1 -> v2 column changes versus the previous draft of this file:
--   * schema_version default+check bumped from 1 to 2.
--   * outfit column RENAMED to clothing (regex '^clothing_[a-z0-9_]{1,40}$').
--   * bg column ADDED (regex '^bg_[a-z0-9_]{1,40}$').
--   * accessory column ADDED (regex '^accessory_[a-z0-9_]{1,40}$').
--   * mouth/eyes/hat columns kept as-is.
-- This stage targets a FRESH apply (create table if not exists with the v2
-- columns below). The live v1 table is NOT migrated by this file. To migrate an
-- existing v1 games.passport_avatars in place, run (reviewed, outside this
-- draft) something like:
--     alter table games.passport_avatars
--       rename column outfit to clothing;
--     alter table games.passport_avatars
--       drop constraint if exists passport_avatars_outfit_check,
--       add constraint passport_avatars_clothing_check
--         check (clothing ~ '^clothing_[a-z0-9_]{1,40}$'),
--       add column bg text not null default 'bg_sky'
--         check (bg ~ '^bg_[a-z0-9_]{1,40}$'),
--       add column accessory text not null default 'accessory_none'
--         check (accessory ~ '^accessory_[a-z0-9_]{1,40}$'),
--       alter column schema_version set default 2,
--       drop constraint if exists passport_avatars_schema_version_check,
--       add constraint passport_avatars_schema_version_check
--         check (schema_version = 2);
--   plus backfilling existing rows' bg/accessory and remapping any legacy
--   'outfit_*' ids to 'clothing_*'. Do this only after review; this file does
--   not touch the live table.
--
-- Trust boundary:
--   * The browser only sends six option IDs. No user ID, badge ID or image.
--   * auth.uid() plus a real Discord identity decide whose row is written.
--   * Option IDs must match the fixed lists below exactly. They mirror the
--     options in docs/meme/avatar-options.json
--     (tests/passport-avatar-sql.test.mjs checks this).
--   * first_avatar is inserted only by the first save, in the same transaction
--     as the avatar row, so a failed save never leaves a badge behind.
--   * A save can be rejected (too fast, daily budget). Errors are never success.
--
-- REWARD PARTS:
--   Some manifest options carry an 'unlock' key. They are saveable only when
--   the player already holds that stamp in games.passport_badges (stamps are
--   awarded by the server, see update_passport_awards.sql); otherwise the save
--   is rejected with 'That part is locked' (errcode 42501). Tampering with the
--   browser cannot unlock them. The reward parts are:
--     hat_hardhat        (unlock rookie_miner: first Pepe Miner cloud save)
--     hat_detective      (unlock detective_fren)
--     clothing_suit      (unlock detective_fren)
--     bg_sunset          (unlock yeet_adept, not earnable yet)
--     accessory_headphones (unlock arcade_hopper, not earnable yet)
--     hat_explorer       (unlock scout_fren)
--     special_explorer   (unlock scout_fren)
--     special_knight     (unlock good_game: a board game played to the end with another Discord player)
--     special_batman, special_vampire, special_smile, special_nerd, special_soldier, special_straw
--                        (unlocked by the secrets why_tho, midnight_fren, happy_fren, nerd_alert, born_to_fren, bali_dreamer)
--     special_seeker (secret_starter), special_scribe (dear_editor), special_editor (senior_editor),
--     special_santa (frogmas), special_looking and special_sherlock (the secrets find_fren, address_check),
--     special_birthday and special_turkey (the event-day stamps pep_birthday, thanksgiving_fren)
--     owner, 2026-11-09: special_gamer (arcade_hopper), special_gigachad (share_fren), special_party (old_frog), special_cupid (valentine_fren), special_juice (welcome_back), special_beanie (streak_14), special_chill (like_it_here), special_bigfren (certified_fren), special_dolphin (nasa_is_hiring), special_retro (fud_buster)
--
-- SPECIAL AVATARS: the 'special' slot holds a whole drawn character (by Lily) for a
-- big milestone. 'special_none' means the normal stacked parts; any other id
-- replaces every part layer except the background in the browser. The parts are
-- still saved, so turning the special avatar off brings the old look back.

create table if not exists games.passport_avatars (
  user_id uuid primary key references auth.users(id) on delete cascade,
  schema_version smallint not null default 2 check (schema_version = 2),
  bg text not null check (bg ~ '^bg_[a-z0-9_]{1,40}$'),
  clothing text not null check (clothing ~ '^clothing_[a-z0-9_]{1,40}$'),
  mouth text not null check (mouth ~ '^mouth_[a-z0-9_]{1,40}$'),
  eyes text not null check (eyes ~ '^eyes_[a-z0-9_]{1,40}$'),
  hat text not null check (hat ~ '^hat_[a-z0-9_]{1,40}$'),
  accessory text not null check (accessory ~ '^accessory_[a-z0-9_]{1,40}$'),
  special text not null default 'special_none' check (special ~ '^special_[a-z0-9_]{1,40}$'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- save budget, never sent to the browser
  budget_day date not null default (now() at time zone 'utc')::date,
  budget_used smallint not null default 1 check (budget_used between 0 and 1000)
);

-- Private table: no direct client access. Only the RPCs below touch it.
alter table games.passport_avatars add column if not exists special text not null default 'special_none'
  check (special ~ '^special_[a-z0-9_]{1,40}$');
alter table games.passport_avatars enable row level security;
revoke all on games.passport_avatars from public, anon, authenticated;

-- the six-part version of this RPC is replaced (one signature only; an old page that sends six parts
-- still works, because p_special has a default)
drop function if exists public.gry_passport_avatar_save(text, text, text, text, text, text);
create or replace function public.gry_passport_avatar_save(
  p_bg text, p_clothing text, p_mouth text, p_eyes text, p_hat text, p_accessory text, p_special text default 'special_none')
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
  cooldown constant interval := interval '3 seconds';
  daily_budget constant integer := 40;
  today date := (now() at time zone 'utc')::date;
  saved games.passport_avatars%rowtype;
  first_save boolean := false;
  changed boolean := true;
  badge_new timestamptz;
  badge_at timestamptz;
begin
  if u is null or games.discord_identity(u) is null then
    raise exception 'Log on with Discord to save your Fren' using errcode = '42501';
  end if;
  -- Exact per-slot allowlists, in manifest order: every part of the manifest,
  -- the free ones first, then the reward parts (the ones with an 'unlock' key).
  if p_bg is null or p_bg not in ('bg_sky', 'bg_night', 'bg_city', 'bg_snow', 'bg_forest', 'bg_sunset')
     or p_clothing is null or p_clothing not in ('clothing_none', 'clothing_blue', 'clothing_purple_hoodie', 'clothing_black_hoodie', 'clothing_shirt_tie', 'clothing_camo', 'clothing_suit')
     or p_mouth is null or p_mouth not in ('mouth_flat', 'mouth_smile', 'mouth_open', 'mouth_tongue', 'mouth_teeth', 'mouth_smirk', 'mouth_shout', 'mouth_wide_tongue', 'mouth_laugh')
     or p_eyes is null or p_eyes not in ('eyes_classic', 'eyes_sleepy', 'eyes_angry', 'eyes_bloodshot', 'eyes_3d', 'eyes_hypno', 'eyes_side', 'eyes_happy', 'eyes_hearts')
     or p_hat is null or p_hat not in ('hat_none', 'hat_pep_cap', 'hat_beanie', 'hat_bucket', 'hat_crown', 'hat_hardhat', 'hat_detective', 'hat_explorer')
     or p_accessory is null or p_accessory not in ('accessory_none', 'accessory_shades', 'accessory_round', 'accessory_orange', 'accessory_cigarette', 'accessory_pipe', 'accessory_headphones')
     or p_special is null or p_special not in ('special_none', 'special_explorer', 'special_batman', 'special_vampire', 'special_smile', 'special_nerd', 'special_soldier', 'special_straw', 'special_knight',
                                                   'special_seeker', 'special_looking', 'special_sherlock', 'special_scribe', 'special_editor',
                                                   'special_birthday', 'special_santa', 'special_turkey',
                                                   'special_gamer', 'special_gigachad', 'special_party', 'special_cupid', 'special_juice', 'special_beanie', 'special_chill', 'special_bigfren', 'special_dolphin', 'special_retro') then
    raise exception 'Unknown avatar option' using errcode = '22023';
  end if;
  -- Reward parts: saveable only by a player who holds the stamp that unlocks them
  -- (the manifest's 'unlock' keys; stamps are awarded by the server only).
  if exists (
    select 1 from (values ('bg_sunset', 'yeet_adept'), ('clothing_suit', 'detective_fren'), ('hat_hardhat', 'rookie_miner'),
                          ('hat_detective', 'detective_fren'), ('accessory_headphones', 'arcade_hopper'),
                          ('hat_explorer', 'scout_fren'), ('special_explorer', 'scout_fren'),
                          ('special_knight', 'good_game'),
                          ('special_batman', 'why_tho'), ('special_vampire', 'midnight_fren'), ('special_smile', 'happy_fren'),
                          ('special_nerd', 'nerd_alert'), ('special_soldier', 'born_to_fren'), ('special_straw', 'bali_dreamer'),
                          ('special_seeker', 'secret_starter'), ('special_looking', 'find_fren'), ('special_sherlock', 'address_check'),
                          ('special_scribe', 'dear_editor'), ('special_editor', 'senior_editor'), ('special_birthday', 'pep_birthday'),
                          ('special_santa', 'frogmas'), ('special_turkey', 'thanksgiving_fren'),
                          ('special_gamer', 'arcade_hopper'), ('special_gigachad', 'share_fren'), ('special_party', 'old_frog'), ('special_cupid', 'valentine_fren'), ('special_juice', 'welcome_back'), ('special_beanie', 'streak_14'), ('special_chill', 'like_it_here'), ('special_bigfren', 'certified_fren'), ('special_dolphin', 'nasa_is_hiring'), ('special_retro', 'fud_buster')) r(part, stamp)
     where r.part in (p_bg, p_clothing, p_hat, p_accessory, p_special)
       -- the unlock is a stamp, or (for most special avatars) a secret
       and not exists (select 1 from games.passport_badges b where b.user_id = u and b.badge_id = r.stamp)
       and not exists (select 1 from games.passport_secrets s where s.user_id = u and s.secret_id = r.stamp)) then
    raise exception 'That part is locked: earn its stamp first' using errcode = '42501';
  end if;

  -- First save. A concurrent first save of the same player waits on the
  -- primary key here, then takes the update path below.
  insert into games.passport_avatars (user_id, bg, clothing, mouth, eyes, hat, accessory, special)
  values (u, p_bg, p_clothing, p_mouth, p_eyes, p_hat, p_accessory, p_special)
  on conflict (user_id) do nothing
  returning * into saved;
  first_save := found;

  if not first_save then
    -- One save at a time per player.
    select * into saved from games.passport_avatars a where a.user_id = u for update;
    changed := (saved.bg, saved.clothing, saved.mouth, saved.eyes, saved.hat, saved.accessory, saved.special)
               is distinct from (p_bg, p_clothing, p_mouth, p_eyes, p_hat, p_accessory, p_special);
    -- Saving the same look again (a double click, a retry) is a no-op success.
    if changed then
      if saved.updated_at > now() - cooldown then
        raise exception 'Saving too fast. Wait a few seconds and try again.' using errcode = 'P0001';
      end if;
      if saved.budget_day = today and saved.budget_used >= daily_budget then
        raise exception 'Daily save limit reached. Your Fren can change again tomorrow (UTC).' using errcode = 'P0001';
      end if;
      update games.passport_avatars a
         set bg = p_bg, clothing = p_clothing, mouth = p_mouth, eyes = p_eyes, hat = p_hat, accessory = p_accessory, special = p_special,
             updated_at = now(),
             budget_used = case when a.budget_day = today then a.budget_used + 1 else 1 end,
             budget_day = today
       where a.user_id = u
      returning * into saved;
    end if;
  else
    -- Fresh Fren: only the first saved look can mint it, once per player.
    insert into games.passport_badges (user_id, badge_id)
    values (u, 'first_avatar')
    on conflict (user_id, badge_id) do nothing
    returning earned_at into badge_new;
  end if;

  select b.earned_at into badge_at
    from games.passport_badges b
   where b.user_id = u and b.badge_id = 'first_avatar';

  return jsonb_build_object(
    'avatar', jsonb_build_object(
      'schema_version', saved.schema_version,
      'bg', saved.bg, 'clothing', saved.clothing,
      'mouth', saved.mouth, 'eyes', saved.eyes, 'hat', saved.hat, 'accessory', saved.accessory, 'special', saved.special),
    'updated_at', saved.updated_at,
    'first_save', first_save,
    'changed', changed,
    'badge', case when badge_at is null then null else jsonb_build_object(
      'id', 'first_avatar', 'earned_at', badge_at, 'new', badge_new is not null) end
  );
end
$$;

revoke all on function public.gry_passport_avatar_save(text, text, text, text, text, text, text) from public, anon, authenticated;
grant execute on function public.gry_passport_avatar_save(text, text, text, text, text, text, text) to authenticated;

-- Passport read path: the same snapshot as update_fren_passport.sql, plus
-- avatar {schema_version, bg, clothing, mouth, eyes, hat, accessory} or null.
-- base ('base_frog') is a constant implied layer and is omitted here to match
-- the manifest note. Keep the two files in sync; this file is the newer one.
create or replace function public.gry_passport_state()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
  d jsonb;
  joined timestamptz;
  best_distance integer := 0;
  best_date timestamptz;
  extra_badges jsonb;
  discovered jsonb;
  owned_items jsonb;
  earned_count integer;
  badge_catalog jsonb;
  look jsonb;
begin
  -- Anonymous Supabase users also have auth.uid(). Require Discord specifically.
  if u is null then
    return jsonb_build_object('signed_in', false);
  end if;
  d := games.discord_identity(u);
  if d is null then
    return jsonb_build_object('signed_in', false);
  end if;

  select au.created_at into joined
    from auth.users au where au.id = u;

  select coalesce(y.best, 0), y.achieved_at
    into best_distance, best_date
    from games.yeet_records y where y.user_id = u;
  best_distance := coalesce(best_distance, 0);

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', b.badge_id,
           'title', case b.badge_id when 'first_avatar' then 'Fresh Fren' else b.badge_id end,
           'description', 'Awarded by a PepecoinHub game',
           'earned_at', b.earned_at) order by b.earned_at), '[]'::jsonb)
    into extra_badges
    from games.passport_badges b where b.user_id = u and b.badge_id <> 'certified_fren';

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.secret_id, 'discovered_at', s.discovered_at)
           order by s.discovered_at), '[]'::jsonb)
    into discovered
    from games.passport_secrets s where s.user_id = u;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', i.item_id, 'quantity', i.quantity, 'earned_at', i.earned_at)
           order by i.earned_at), '[]'::jsonb)
    into owned_items
    from games.passport_items i where i.user_id = u;

  select jsonb_build_object('schema_version', a.schema_version,
           'bg', a.bg, 'clothing', a.clothing,
           'mouth', a.mouth, 'eyes', a.eyes, 'hat', a.hat, 'accessory', a.accessory, 'special', a.special)
    into look
    from games.passport_avatars a where a.user_id = u;

  badge_catalog := jsonb_build_array(
    jsonb_build_object('id', 'first_fren', 'title', 'First Fren',
      'description', 'Joined the pond with Discord.', 'earned_at', joined),
    jsonb_build_object('id', 'moonwalker', 'title', 'Moonwalker',
      'description', 'Recorded a 6000 m YEET flight. Moon Rock inventory validation is not enabled yet.',
      'earned_at', case when best_distance = 60000 then best_date else null end),
    jsonb_build_object('id', 'certified_fren', 'title', 'Certified Fren',
      'description', '100 distinct care days in PepeGochi.',
      'earned_at', (select b.earned_at from games.passport_badges b
                    where b.user_id = u and b.badge_id = 'certified_fren'))
  );
  select count(*) into earned_count from jsonb_array_elements(badge_catalog) x
    where x->>'earned_at' is not null;
  earned_count := earned_count + jsonb_array_length(extra_badges);

  return jsonb_build_object(
    'signed_in', true,
    'nickname', coalesce(nullif(d->>'name', ''), 'Discord fren'),
    'member_since', joined,
    'yeet_best', best_distance,
    'achievements', badge_catalog || extra_badges,
    'achievements_earned', earned_count,
    'secrets', discovered,
    'items', owned_items,
    'avatar', look,
    'care_days', null
  );
end
$$;

revoke all on function public.gry_passport_state() from public, anon, authenticated;
grant execute on function public.gry_passport_state() to authenticated;

-- ====================================================================================================
-- 11/17  update_passport_awards.sql
-- ====================================================================================================
-- Fren Passport: stamps the server can verify, awarded by the games themselves.
-- DRAFT. Apply to PH-games only after review, in this order:
--   update_fren_passport.sql -> update_fren_avatar.sql -> this file.
-- It also needs the game migrations it hooks into (already on production):
--   update_yeet.sql, update_wheres_pepe.sql (+ _guests), update_lobby_chat.sql, update_open_chat.sql,
--   update_lobby_mentions.sql, update_frog_letters.sql, update_letters_community.sql, update_miner_cloud.sql.
-- Safe to run twice.
--
-- RUN IT ON LAUNCH DAY. The first run takes the Pond Pioneer snapshot: accounts with
-- Discord linked BEFORE the Passport opens get the stamp; later arrivals cannot earn it.
-- Later runs never add anyone (games.passport_meta remembers the snapshot).
--
-- Trust rules (games/FREN_PASSPORT_ACHIEVEMENTS_DECISIONS_2026-11-06.md):
--   * Only events the server itself records can award a stamp. Nothing here takes a badge id, a count,
--     a score or a time from the browser. Stamps that only the browser could see (opening a folder,
--     starting a game) are deliberately not built.
--   * Discord accounts only: games.passport_award() checks games.discord_identity() on every award.
--   * Each stamp is one row in games.passport_badges (primary key user_id + badge_id), so it is awarded
--     once. Stamps never unlock PEP, points or anything transferable.
--   * The hooks are triggers on the existing game tables (plus one line in gry_yeet_submit). A failure
--     inside a hook is caught and logged as a warning, so a stamp bug can never break a game.
--   * YEET distances are still client-reported with plausibility checks only (update_yeet.sql), so the
--     YEET stamps are cosmetic, like the leaderboard.
--
-- Stamps awarded here (the ids must match docs/meme/passport-catalog.json; tests check it):
--   pond_pioneer    Discord linked when this file first runs (one-time snapshot)
--   moonwalker      a YEET flight of 6000 m (the maximum); old records are backfilled
--   nasa_is_hiring  three accepted YEET flights over 5000 m; the first three are kept in passport_yeet_5k
--   pepe_guesser    first Pepe Guesser guess with a pin on the map (Discord-verified play)
--   sharp_eye       first perfect 5000
--   detective_fren  5000 on five different puzzle days
--   week_scout      a guess on 7 puzzle days in a row (UTC)
--   scout_fren      a guess on 14 puzzle days in a row (UTC)
--   welcome_back    back in PondOS on the day after the first visit (gry_passport_checkin)
--   streak_14       PondOS opened signed in on 14 UTC days in a row (gry_passport_checkin)
--   like_it_here    PondOS opened signed in on 30 UTC days in a row (gry_passport_checkin)
--   first_words     first lobby chat message
--   community_fren  lobby chat on five different UTC days
--   hey_fren        first @mention of another fren (games.lobby_mentions)
--   dear_editor     first letter to the editor
--   rookie_miner    "Happy Mining!": the first Pepe Miner cloud save (unlocks the hard hat)
--   junior_editor, senior_editor, vox_populi   1, 5 and 10 letters the owner marked "Printed" (gry_letter_printed)
--   (bug_hunter waits: the owner adds it later if needed, 2026-11-09)
--   bali            for every fren once the owner opens it, the day Pepecoin reaches $0.01 (gry_passport_bali)
-- The editor stamps are never awarded from the number of letters sent (owner, 2026-11-08).
-- Pepe Guesser, letters and Moonwalker are backfilled from existing records. Chat history is kept only
-- 24 h and YEET keeps only the best flight, so those stamps count from the day this file runs.
--
-- Stamps added later: everything a future stamp might count is kept from today on (PondOS days, chat
-- days, letters, Miner seconds, every accepted YEET flight and every one over 5000 m, and all Pepe Guesser
-- plays). A later migration can add a stamp with its own backfill from these records, so players keep
-- the progress they already have.

-- ---------- storage ----------
alter table games.passport_badges add column if not exists notified_at timestamptz;   -- shown once by gry_passport_checkin

create table if not exists games.passport_meta (
  k  text primary key check (k ~ '^[a-z_]{3,40}$'),
  at timestamptz not null default clock_timestamp()
);
-- the first three YEET flights over 5000 m (tenths of a metre), one row per accepted flight
create table if not exists games.passport_yeet_5k (
  user_id  uuid not null references auth.users(id) on delete cascade,
  n        smallint not null check (n between 1 and 3),
  distance integer not null check (distance > 50000 and distance <= 60000),
  flown_at timestamptz not null default clock_timestamp(),
  primary key (user_id, n)
);
-- UTC days on which a Discord player opened PondOS (gry_passport_checkin)
create table if not exists games.passport_days (
  user_id uuid not null references auth.users(id) on delete cascade,
  day     date not null,
  primary key (user_id, day)
);
-- UTC days on which a Discord player wrote in the lobby chat (the chat itself is deleted after 24 h)
create table if not exists games.passport_chat_days (
  user_id uuid not null references auth.users(id) on delete cascade,
  day     date not null,
  primary key (user_id, day)
);
-- counters the server keeps itself: letters sent, Pepe Miner seconds, accepted YEET flights
create table if not exists games.passport_progress (
  user_id       uuid primary key references auth.users(id) on delete cascade,
  letters       integer not null default 0 check (letters >= 0),
  miner_seconds integer not null default 0 check (miner_seconds >= 0),
  miner_last_at timestamptz,
  yeet_flights  integer not null default 0 check (yeet_flights >= 0),
  yeet_5k_total integer not null default 0 check (yeet_5k_total >= 0)
);
alter table games.passport_progress add column if not exists yeet_flights integer not null default 0 check (yeet_flights >= 0);
alter table games.passport_progress add column if not exists yeet_5k_total integer not null default 0 check (yeet_5k_total >= 0);
-- Frog of the Week is the only repeatable stamp: how many weeks it was won
alter table games.passport_badges add column if not exists times integer not null default 1 check (times >= 1);
-- each finished Pepe Guesser week and each finished Pepe Pictures season is settled once
create table if not exists games.passport_weeks (week_start date primary key, settled_at timestamptz not null default clock_timestamp());
create table if not exists games.passport_seasons (season_no integer primary key, settled_at timestamptz not null default clock_timestamp());
alter table games.passport_weeks enable row level security;
alter table games.passport_seasons enable row level security;
alter table games.passport_meta enable row level security;
alter table games.passport_yeet_5k enable row level security;
alter table games.passport_days enable row level security;
alter table games.passport_chat_days enable row level security;
alter table games.passport_progress enable row level security;
revoke all on games.passport_meta, games.passport_yeet_5k, games.passport_days, games.passport_chat_days,
  games.passport_progress from public, anon, authenticated;

-- ---------- the one award path ----------
create or replace function games.passport_award(u uuid, b text, at timestamptz default null)
returns boolean language plpgsql volatile security definer set search_path = '' as $$
begin
  if b is null or b not in ('pond_pioneer', 'moonwalker', 'nasa_is_hiring', 'pepe_guesser', 'sharp_eye',
      'detective_fren', 'week_scout', 'scout_fren', 'welcome_back', 'streak_14', 'like_it_here', 'first_words',
      'community_fren', 'hey_fren', 'dear_editor', 'rookie_miner', 'good_game', 'checkmate',
      'i_voted', 'yeet_adept', 'fud_buster', 'long_snake', 'secret_starter', 'treasure_hunter', 'podium', 'game_night',
      'quiz_master', 'certified_fren', 'old_frog', 'arcade_hopper', 'frogmas', 'season_champion', 'frog_of_the_week',
      'junior_editor', 'senior_editor', 'vox_populi', 'bali', 'pep_birthday', 'thanksgiving_fren', 'valentine_fren',
      'first_hatch', 'little_fren', 'grown_fren', 'good_parent', 'interior_designer', 'picasso_fren',
      'pond_dominator') then
    raise exception 'Unknown passport stamp %', b;
  end if;
  if u is null or games.discord_identity(u) is null then return false; end if;
  insert into games.passport_badges (user_id, badge_id, earned_at)
  values (u, b, coalesce(at, clock_timestamp()))
  on conflict (user_id, badge_id) do nothing;
  return found;
end
$$;

-- ---------- YEET THE PEP ----------
create or replace function games.passport_yeet_flight(u uuid, p_score integer)
returns void language plpgsql volatile security definer set search_path = '' as $$
declare kept integer;
begin
  if p_score is null then return; end if;
  -- every accepted flight is counted, for stamps that may be added later
  insert into games.passport_progress (user_id, yeet_flights, yeet_5k_total)
  values (u, 1, case when p_score > 50000 then 1 else 0 end)
  on conflict (user_id) do update set
    yeet_flights = games.passport_progress.yeet_flights + 1,
    yeet_5k_total = games.passport_progress.yeet_5k_total + excluded.yeet_5k_total;
  if p_score >= 30000 then perform games.passport_award(u, 'yeet_adept'); end if;   -- 3000 m
  if p_score >= 60000 then perform games.passport_award(u, 'moonwalker'); end if;
  if p_score <= 50000 then return; end if;
  -- the caller holds this player's games.yeet_records row lock, so flights are counted one at a time
  select count(*) into kept from games.passport_yeet_5k f where f.user_id = u;
  if kept >= 3 then return; end if;
  insert into games.passport_yeet_5k (user_id, n, distance) values (u, kept + 1, p_score)
  on conflict (user_id, n) do nothing;
  if kept + 1 >= 3 then perform games.passport_award(u, 'nasa_is_hiring'); end if;
end
$$;

-- Same as update_yeet.sql, plus the passport hook after an accepted (not rate-limited) flight.
-- tests/passport-awards.test.mjs checks that the rest of the body still matches update_yeet.sql.
create or replace function public.gry_yeet_submit(p_score integer, p_ms integer, p_version integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  u uuid := auth.uid(); d jsonb; r games.yeet_records;
  v_nick text; saved boolean := false;
begin
  if u is null then raise exception 'Log in with Discord to save a flight'; end if;
  d := games.discord_identity(u);
  if d is null then raise exception 'Log in with Discord to save a flight'; end if;
  if p_version is distinct from 1 then raise exception 'Refresh the game before submitting'; end if;
  if p_score is null or p_score < 1 or p_score > 60000 then raise exception 'Invalid flight distance'; end if;
  if p_ms is null or p_ms < 1000 or p_ms > 360500 then raise exception 'Invalid flight duration'; end if;
  -- At most 100 m/s in v1; tolerate rounding and initial launch/collision steps.
  if p_score::bigint > p_ms::bigint + 100 then raise exception 'That distance does not match the flight time'; end if;
  v_nick := left(btrim(regexp_replace(coalesce(d->>'name', 'Discord pilot'), '[[:cntrl:]]', '', 'g')), 40);
  if v_nick = '' then v_nick := 'Discord pilot'; end if;
  insert into games.yeet_records(user_id, nick) values (u, v_nick) on conflict (user_id) do nothing;
  select * into strict r from games.yeet_records where user_id = u for update;
  -- A per-account lock makes simultaneous submissions monotonic and enforces cooldown atomically.
  if r.last_attempt_at > clock_timestamp() - interval '10 seconds' then
    return jsonb_build_object('best', r.best, 'saved', false, 'rate_limited', true);
  end if;
  saved := p_score > r.best;
  update games.yeet_records set nick = v_nick,
    best = greatest(best, p_score),
    duration_ms = case when p_score > best then p_ms else duration_ms end,
    achieved_at = case when p_score > best then clock_timestamp() else achieved_at end,
    last_attempt_at = clock_timestamp()
  where user_id = u;
  -- Fren Passport (update_passport_awards.sql): count the flight; a stamp bug never loses the flight.
  begin
    perform games.passport_yeet_flight(u, p_score);
  exception when others then
    raise warning 'passport yeet hook: %', sqlerrm;
  end;
  return jsonb_build_object('best', greatest(r.best, p_score), 'saved', saved,
                           'rate_limited', false, 'top', games.yeet_top());
end $$;
revoke all on function public.gry_yeet_submit(integer, integer, integer) from public, anon, authenticated;
grant execute on function public.gry_yeet_submit(integer, integer, integer) to authenticated;

-- ---------- Pepe Guesser ----------
-- Re-reads this player's Discord-verified plays with a pin and awards whatever they reached.
-- One row per (puzzle, player) and one puzzle per UTC day, so every count is in different days.
create or replace function games.passport_wp_check(u uuid)
returns void language plpgsql volatile security definer set search_path = '' as $$
declare r record;
begin
  if u is null or games.discord_identity(u) is null then return; end if;
  with p as (
    select q.day, x.guessed_at as at, x.points
      from games.wp_plays x join games.wp_puzzles q on q.id = x.puzzle_id
     where x.user_id = u and x.verified and x.g_lat is not null and x.guessed_at is not null and q.day is not null),
  g as (
    select day, at, points,
           row_number() over (order by day) as k,
           case when points = 5000 then row_number() over (partition by points = 5000 order by day) end as k5,
           day - (row_number() over (order by day))::integer as grp
      from p),
  s as (select at, k, k5, row_number() over (partition by grp order by day) as run from g)
  select min(at) filter (where k = 1) as first_guess,
         min(at) filter (where k5 = 1) as first_perfect,
         min(at) filter (where k5 = 5) as five_perfect,
         min(at) filter (where run = 7) as run7,
         min(at) filter (where run = 14) as run14
    into r from s;
  if r.first_guess is not null then perform games.passport_award(u, 'pepe_guesser', r.first_guess); end if;
  if r.first_perfect is not null then perform games.passport_award(u, 'sharp_eye', r.first_perfect); end if;
  if r.five_perfect is not null then perform games.passport_award(u, 'detective_fren', r.five_perfect); end if;
  if r.run7 is not null then perform games.passport_award(u, 'week_scout', r.run7); end if;
  if r.run14 is not null then perform games.passport_award(u, 'scout_fren', r.run14); end if;
end
$$;

-- current run of puzzle days with a pin, ending today (or yesterday, if today is not played yet)
create or replace function games.passport_wp_streak(u uuid)
returns integer language plpgsql stable security definer set search_path = '' as $$
declare d date := (now() at time zone 'utc')::date; s integer := 0;
  played boolean;
begin
  played := exists (select 1 from games.wp_plays x join games.wp_puzzles q on q.id = x.puzzle_id
                     where x.user_id = u and x.verified and x.g_lat is not null and q.day = d);
  if not played then d := d - 1; end if;
  while s < 400 and exists (select 1 from games.wp_plays x join games.wp_puzzles q on q.id = x.puzzle_id
                     where x.user_id = u and x.verified and x.g_lat is not null and q.day = d - s) loop
    s := s + 1;
  end loop;
  return s;
end
$$;

create or replace function games.passport_wp_after()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.guessed_at is not null and old.guessed_at is null and new.g_lat is not null and new.verified then
    begin
      perform games.passport_wp_check(new.user_id);
    exception when others then
      raise warning 'passport wp hook: %', sqlerrm;
    end;
  end if;
  return null;
end
$$;
drop trigger if exists passport_wp_au on games.wp_plays;
create trigger passport_wp_au after update of guessed_at on games.wp_plays
  for each row execute function games.passport_wp_after();

-- ---------- lobby chat (PEP Games lobby and LAN Party) ----------
create or replace function games.passport_chat_after()
returns trigger language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  if new.verified and new.user_id is not null then
    begin
      insert into games.passport_chat_days (user_id, day)
      values (new.user_id, (new.created_at at time zone 'utc')::date)
      on conflict (user_id, day) do nothing;
      if found then   -- first message of the day: the only time the counts can change
        perform games.passport_award(new.user_id, 'first_words', new.created_at);
        select count(*) into n from games.passport_chat_days where user_id = new.user_id;
        if n >= 5 then perform games.passport_award(new.user_id, 'community_fren', new.created_at); end if;
      end if;
      -- two chat secrets (each unlocks a special avatar): a smiley, and the word "fren"
      if games.discord_identity(new.user_id) is not null then
        if new.body ~ '(:-?\)|\(:)' then
          insert into games.passport_secrets (user_id, secret_id, discovered_at) values (new.user_id, 'happy_fren', new.created_at)
          on conflict (user_id, secret_id) do nothing;
        end if;
        -- @mentions do not count: a nickname like @Fren6 is not saying the word
        if regexp_replace(new.body, '@\S+', '', 'g') ~* '(^|[^a-z])frens?([^a-z]|$)' then
          insert into games.passport_secrets (user_id, secret_id, discovered_at) values (new.user_id, 'born_to_fren', new.created_at)
          on conflict (user_id, secret_id) do nothing;
        end if;
      end if;
    exception when others then
      raise warning 'passport chat hook: %', sqlerrm;
    end;
  end if;
  return null;
end
$$;
drop trigger if exists passport_chat_ai on games.lobby_chat;
create trigger passport_chat_ai after insert on games.lobby_chat
  for each row execute function games.passport_chat_after();

-- ---------- board games (chess, checkers, Connect Four, Sea Battle) ----------
-- Good Game: a game played to its end by two different Discord players. A resignation, a player who left,
-- an aborted game and very short games (fewer than 10 moves; Sea Battle always takes longer) do not count.
-- Checkmate!: the winner of a chess game that ended in checkmate under the same conditions.
create or replace function games.passport_table_after()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v1 boolean; v2 boolean; w uuid;
begin
  if new.status = 'finished' and old.status is distinct from 'finished' and new.result is not null
     and new.p1 is not null and new.p2 is not null and new.p1 <> new.p2 then
    begin
      if coalesce(new.reason, '') ~* '(resigned|left the table|players left|did not place|did not make)' then return null; end if;
      if new.game <> 'battleship' and coalesce(array_length(new.history, 1), 0) < 10 then return null; end if;
      select coalesce(bool_or(m.verified) filter (where m.user_id = new.p1), false),
             coalesce(bool_or(m.verified) filter (where m.user_id = new.p2), false)
        into v1, v2 from games.table_members m where m.table_code = new.code;
      if not (v1 and v2) then return null; end if;
      perform games.passport_award(new.p1, 'good_game');
      perform games.passport_award(new.p2, 'good_game');
      if new.game = 'chess' and new.reason = 'checkmate' and new.result in ('p1', 'p2') then
        w := case new.result when 'p1' then new.p1 else new.p2 end;
        perform games.passport_award(w, 'checkmate');
      end if;
    exception when others then
      raise warning 'passport table hook: %', sqlerrm;
    end;
  end if;
  return null;
end
$$;
drop trigger if exists passport_table_au on games.tables;
create trigger passport_table_au after update of status on games.tables
  for each row execute function games.passport_table_after();

-- a mention row exists only when a verified player really @mentioned another reserved nickname
create or replace function games.passport_mention_after()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  begin
    if not exists (select 1 from games.passport_badges b where b.user_id = new.from_user and b.badge_id = 'hey_fren') then
      perform games.passport_award(new.from_user, 'hey_fren', new.created_at);
    end if;
  exception when others then
    raise warning 'passport mention hook: %', sqlerrm;
  end;
  return null;
end
$$;
drop trigger if exists passport_mention_ai on games.lobby_mentions;
create trigger passport_mention_ai after insert on games.lobby_mentions
  for each row execute function games.passport_mention_after();

-- ---------- letters to the editor ----------
create or replace function games.passport_letter_after()
returns trigger language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  if new.discord then
    begin
      insert into games.passport_progress (user_id, letters) values (new.user_id, 1)
      on conflict (user_id) do update set letters = games.passport_progress.letters + 1
      returning letters into n;
      if n >= 1 then perform games.passport_award(new.user_id, 'dear_editor', new.created_at); end if;
    exception when others then
      raise warning 'passport letter hook: %', sqlerrm;
    end;
  end if;
  return null;
end
$$;
drop trigger if exists passport_letter_ai on games.letters;
create trigger passport_letter_ai after insert on games.letters
  for each row execute function games.passport_letter_after();

-- ---------- Picasso Fren: other players guessed 10 of your drawings in Draw & Guess ----------
-- Draw & Guess (rooms in mode 'kalambury') is run by the server: gry_guess() marks a correct guess by setting
-- games.players.guessed_turn. A drawing counts once (per turn) when a different, verified (Discord) player
-- guesses it, and the drawer is a Discord player too. Kept in its own table, so finished rooms can be deleted.
create table if not exists games.passport_drawings (
  turn_id    uuid primary key,
  drawer_id  uuid not null references auth.users(id) on delete cascade,
  guessed_at timestamptz not null default clock_timestamp()
);
create index if not exists passport_drawings_drawer on games.passport_drawings (drawer_id);
alter table games.passport_drawings enable row level security;

create or replace function games.passport_drawing_after()
returns trigger language plpgsql security definer set search_path = '' as $$
declare r record; n integer;
begin
  if new.guessed_turn is null or new.guessed_turn is not distinct from old.guessed_turn or not new.verified then return null; end if;
  select x.mode, x.drawer_id, x.turn_id into r from games.rooms x where x.code = new.room_code;
  if not found or r.mode <> 'kalambury' or r.drawer_id is null or r.drawer_id = new.user_id
     or r.turn_id is distinct from new.guessed_turn or games.discord_identity(r.drawer_id) is null
     or games.discord_identity(new.user_id) is null then
    return null;
  end if;
  begin
    insert into games.passport_drawings (turn_id, drawer_id) values (new.guessed_turn, r.drawer_id) on conflict (turn_id) do nothing;
    select count(*) into n from games.passport_drawings d where d.drawer_id = r.drawer_id;
    if n >= 10 then perform games.passport_award(r.drawer_id, 'picasso_fren'); end if;
  exception when others then
    raise warning 'passport drawing: %', sqlerrm;   -- never undoes the guess
  end;
  return null;
end
$$;
revoke all on function games.passport_drawing_after() from public, anon, authenticated;
do $$
begin
  if to_regclass('games.players') is not null then
    drop trigger if exists passport_drawing_au on games.players;
    create trigger passport_drawing_au after update of guessed_turn on games.players
      for each row execute function games.passport_drawing_after();
  end if;
end $$;

-- ---------- owner tools: "Printed" letters, BALI ----------
-- Junior Editor (1), Senior Editor (5) and Vox Populi (10) count the letters the owner marked as printed
-- in The Pond Gazette. Only letters whose writer ticked "OK to print" can be marked. The marks live in
-- their own table, because games.letters deletes read letters beyond the newest 2000 and the count must
-- not drop. Unmarking a letter (a mis-click) takes back a stamp the count no longer reaches.
create table if not exists games.passport_printed (
  letter_id  bigint primary key,
  user_id    uuid not null references auth.users(id) on delete cascade,
  printed_at timestamptz not null default clock_timestamp()
);
create index if not exists passport_printed_user on games.passport_printed (user_id);
alter table games.passport_printed enable row level security;

create or replace function games.passport_printed_check(u uuid)
returns integer language plpgsql volatile security definer set search_path = '' as $$
declare n integer;
begin
  select count(*) into n from games.passport_printed p where p.user_id = u;
  if n >= 1 then perform games.passport_award(u, 'junior_editor'); end if;
  if n >= 5 then perform games.passport_award(u, 'senior_editor'); end if;
  if n >= 10 then perform games.passport_award(u, 'vox_populi'); end if;
  delete from games.passport_badges b
   where b.user_id = u and ((b.badge_id = 'junior_editor' and n < 1) or (b.badge_id = 'senior_editor' and n < 5)
                            or (b.badge_id = 'vox_populi' and n < 10));
  return n;
end
$$;
revoke all on function games.passport_printed_check(uuid) from public, anon, authenticated;

create or replace function public.gry_letter_printed(p_id bigint, p_printed boolean)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare l record; n integer := 0;
begin
  if not games.is_owner(auth.uid()) then raise exception 'Only the site owner can do that'; end if;
  select x.id, x.user_id, x.discord, x.print_ok into l from games.letters x where x.id = p_id;
  if not found then raise exception 'That letter is gone'; end if;
  if coalesce(p_printed, false) then
    if not l.print_ok then raise exception 'This fren did not tick "OK to print", so it cannot be marked as printed'; end if;
    insert into games.passport_printed (letter_id, user_id) values (l.id, l.user_id) on conflict (letter_id) do nothing;
  else
    delete from games.passport_printed p where p.letter_id = l.id;
  end if;
  if l.discord then n := games.passport_printed_check(l.user_id); end if;
  return jsonb_build_object('ok', true, 'printed', coalesce(p_printed, false), 'printed_count', n);
end
$$;
revoke all on function public.gry_letter_printed(bigint, boolean) from public, anon;
grant execute on function public.gry_letter_printed(bigint, boolean) to authenticated;

-- Bug Hunter waits (owner, 2026-11-09): no grant tool at launch. An earlier draft's function is removed.
drop function if exists public.gry_letter_bug_hunter(bigint, boolean);

-- BALI: the owner opens it on the day Pepecoin reaches $0.01. From then on every Discord fren gets the
-- mythic stamp on their next PondOS visit (games.passport_daily). Closing it again stops new awards and
-- takes nothing back.
create or replace function public.gry_passport_bali(p_open boolean)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
begin
  if not games.is_owner(auth.uid()) then raise exception 'Only the site owner can do that'; end if;
  if coalesce(p_open, false) then
    insert into games.passport_meta (k) values ('bali_open') on conflict (k) do nothing;
    perform games.passport_award(auth.uid(), 'bali');
  else
    delete from games.passport_meta m where m.k = 'bali_open';
  end if;
  return jsonb_build_object('ok', true, 'bali_open', exists (select 1 from games.passport_meta m where m.k = 'bali_open'));
end
$$;
revoke all on function public.gry_passport_bali(boolean) from public, anon;
grant execute on function public.gry_passport_bali(boolean) to authenticated;

-- Share Fren (owner, 2026-11-10): a small cosmetic secret when a Discord fren copies/shares
-- a finished Pepe Guesser result. The browser cannot prove an X post, so never award a stamp.
-- This RPC takes no client-provided score or badge name and checks the player's own record.
create or replace function public.gry_passport_share()
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare u uuid := auth.uid(); new_discovery timestamptz;
begin
  if u is null or games.discord_identity(u) is null then raise exception 'Log on with Discord to save secrets'; end if;
  if exists (select 1 from games.wp_plays p where p.user_id = u and p.guessed_at is not null) then
    insert into games.passport_secrets(user_id, secret_id)
    values (u, 'share_fren')
    on conflict (user_id, secret_id) do nothing
    returning discovered_at into new_discovery;
  end if;
  return jsonb_build_object('id', 'share_fren', 'new', new_discovery is not null,
    'found', exists (select 1 from games.passport_secrets s where s.user_id = u and s.secret_id = 'share_fren'));
end
$$;
revoke all on function public.gry_passport_share() from public, anon;
grant execute on function public.gry_passport_share() to authenticated;

-- The owner's mailbox: as update_letters_community.sql, plus each letter's "printed" mark, whether its
-- how many of the writer's letters were printed, and whether BALI is open.
create or replace function public.gry_letters(p_limit int default 100)
returns jsonb
language plpgsql security definer set search_path = ''
as $fn$
declare
  lim int := least(greatest(coalesce(p_limit, 100), 1), 500);
begin
  if not games.is_owner(auth.uid()) then
    return null;
  end if;
  return jsonb_build_object(
    'unread', (select count(*) from games.letters where read_at is null),
    'bali_open', exists (select 1 from games.passport_meta m where m.k = 'bali_open'),
    'letters', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', q.id, 'at', q.created_at, 'name', q.name,
               'discord', q.discord, 'print', q.print_ok, 'body', q.body,
               'page', q.page, 'read', q.read_at is not null,
               'printed', exists (select 1 from games.passport_printed p where p.letter_id = q.id),
               'printed_count', case when q.discord then (select count(*) from games.passport_printed p where p.user_id = q.user_id) else 0 end)
             order by q.created_at desc)
      from (select * from games.letters
            order by created_at desc limit lim) q), '[]'::jsonb));
end
$fn$;
revoke all on function public.gry_letters(int) from public, anon;
grant execute on function public.gry_letters(int) to authenticated;

-- ---------- Pepe Miner ----------
-- The game sends its cloud save every 60 s while it runs (docs/games/js/miner.js), and gry_miner_save
-- accepts at most one save per 20 s. Play time is the server's own clock between two accepted saves
-- that are at most 120 s apart; a longer gap starts a new session. The game's own numbers are ignored.
create or replace function games.passport_miner_after()
returns trigger language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  begin
    insert into games.passport_progress (user_id, miner_last_at) values (new.user_id, clock_timestamp())
    on conflict (user_id) do update set
      miner_seconds = games.passport_progress.miner_seconds
        + case when games.passport_progress.miner_last_at > clock_timestamp() - interval '120 seconds'
               then greatest(0, ceil(extract(epoch from clock_timestamp() - games.passport_progress.miner_last_at)))::integer
               else 0 end,
      miner_last_at = clock_timestamp()
    returning miner_seconds into n;
    -- Happy Mining!: the first cloud save (v3). Play time is still counted for a future stamp.
    perform games.passport_award(new.user_id, 'rookie_miner');
  exception when others then
    raise warning 'passport miner hook: %', sqlerrm;
  end;
  return null;
end
$$;
drop trigger if exists passport_miner_aiu on games.miner_saves;
create trigger passport_miner_aiu after insert or update on games.miner_saves
  for each row execute function games.passport_miner_after();

-- ---------- PondOS visits: Welcome Back!, 14-Day Streak, Guess You Like It Here, and new-stamp notices ----------
-- Called by PondOS (docs/meme/meme.js) when a Discord player opens a page. It writes one row per UTC day
-- at most, and hands back the stamps the player has not been told about yet (each one only once).
-- ---------- Pond Polls: I Voted ----------
create or replace function games.passport_poll_after()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.verified then
    begin perform games.passport_award(new.user_id, 'i_voted', new.voted_at);
    exception when others then raise warning 'passport poll hook: %', sqlerrm; end;
  end if;
  return null;
end
$$;

-- ---------- FUD Invaders and PEP Snake: FUD Buster (2,000 points), Long Snake (40 blocks) ----------
create or replace function games.passport_arcade_after()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.verified and new.user_id is not null then
    begin
      if new.game = 'fud' and new.score >= 2000 then perform games.passport_award(new.user_id, 'fud_buster', new.created_at); end if;
      if new.game = 'snake' and new.score >= 40 then perform games.passport_award(new.user_id, 'long_snake', new.created_at); end if;
    exception when others then raise warning 'passport arcade hook: %', sqlerrm; end;
  end if;
  return null;
end
$$;

-- ---------- secrets: Secret Starter (1), Treasure Hunter (10; owner, 2026-11-09) ----------
create or replace function games.passport_secret_after()
returns trigger language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  begin
    select count(*) into n from games.passport_secrets where user_id = new.user_id;
    if n >= 1 then perform games.passport_award(new.user_id, 'secret_starter', new.discovered_at); end if;
    if n >= 10 then perform games.passport_award(new.user_id, 'treasure_hunter', new.discovered_at); end if;
  exception when others then raise warning 'passport secret hook: %', sqlerrm; end;
  return null;
end
$$;

-- ---------- Pepe Pictures: Podium (top 3), Game Night (a scheduled night), Quiz Master (hosted, 4+ ranked players) ----------
create or replace function games.passport_result_after()
returns trigger language plpgsql security definer set search_path = '' as $$
declare m games.matches; host uuid; n integer;
begin
  begin
    select * into m from games.matches where id = new.match_id;
    if m.id is null or m.mode <> 'obrazek' then return null; end if;
    if new.verified then
      if new.place <= 3 then perform games.passport_award(new.user_id, 'podium', new.finished_at); end if;
      if exists (select 1 from games.events e where e.room_code = m.room_code
                   and e.starts_at between m.started_at - interval '3 hours' and m.started_at + interval '3 hours') then
        perform games.passport_award(new.user_id, 'game_night', new.finished_at);
      end if;
    end if;
    select count(*) into n from games.results where match_id = new.match_id;
    if n >= 4 then
      select r.host_id into host from games.rooms r where r.code = m.room_code;
      if host is not null and host <> new.user_id then perform games.passport_award(host, 'quiz_master', new.finished_at); end if;
    end if;
  exception when others then raise warning 'passport result hook: %', sqlerrm; end;
  return null;
end
$$;

-- the triggers are created only where the game tables exist (every game migration runs before this file)
do $$ begin
  if to_regclass('games.poll_votes') is not null then
    drop trigger if exists passport_poll_ai on games.poll_votes;
    create trigger passport_poll_ai after insert on games.poll_votes for each row execute function games.passport_poll_after();
  end if;
  if to_regclass('games.arcade_scores') is not null then
    drop trigger if exists passport_arcade_ai on games.arcade_scores;
    create trigger passport_arcade_ai after insert on games.arcade_scores for each row execute function games.passport_arcade_after();
  end if;
  drop trigger if exists passport_secret_ai on games.passport_secrets;
  create trigger passport_secret_ai after insert on games.passport_secrets for each row execute function games.passport_secret_after();
  drop trigger if exists passport_result_ai on games.results;
  create trigger passport_result_ai after insert on games.results for each row execute function games.passport_result_after();
end $$;

-- ---------- daily rules, run by the check-in (once a visit) ----------
-- Pepe Guesser points of one player in a date range (verified plays only), and the same for a whole board
create or replace function games.passport_daily(u uuid)
returns void language plpgsql volatile security definer set search_path = '' as $$
declare
  today date := (now() at time zone 'utc')::date;
  wk date := (date_trunc('week', (now() at time zone 'utc'))::date) - 7;   -- last finished Monday-Sunday week
  joined timestamptz;
  games_played integer := 0;
  mine numeric;
  se jsonb := games.season_at(now());
  cur integer := (se->>'no')::int;
  w record;
  sn integer;
  tg date;
  hof date;
begin
  -- Certified Fren: 100 different UTC days
  if (select count(*) from games.passport_days where user_id = u) >= 100 then perform games.passport_award(u, 'certified_fren'); end if;
  -- Old Frog: one year since the first Discord log-on (the Discord identity's creation time)
  select min(coalesce((to_jsonb(i)->>'created_at')::timestamptz, au.created_at)) into joined
    from auth.identities i join auth.users au on au.id = i.user_id where i.user_id = u and i.provider = 'discord';
  if joined is not null and joined <= now() - interval '365 days' then perform games.passport_award(u, 'old_frog'); end if;
  -- BALI: the owner opened it (gry_passport_bali), so every fren gets it on the next visit
  if exists (select 1 from games.passport_meta m where m.k = 'bali_open') then perform games.passport_award(u, 'bali'); end if;
  -- Event days for every fren who visits (each is a stamp, like Frogmas, and unlocks a special avatar):
  -- Pepecoin's birthday, 30 January (UTC 30-31, so every time zone has its 30th), and US Thanksgiving,
  -- the fourth Thursday of November, through that Sunday
  if extract(month from today) = 1 and extract(day from today) between 30 and 31 then
    perform games.passport_award(u, 'pep_birthday');
  end if;
  -- Valentine's Day (owner, 2026-11-09): 14 February (UTC 14-15, so every time zone has its 14th)
  if extract(month from today) = 2 and extract(day from today) between 14 and 15 then
    perform games.passport_award(u, 'valentine_fren');
  end if;
  tg := make_date(extract(year from today)::int, 11, 1);
  tg := tg + ((4 - extract(dow from tg)::int + 7) % 7) + 21;
  if today between tg and tg + 3 then
    perform games.passport_award(u, 'thanksgiving_fren');
  end if;
  -- Frogmas: a visit on 24, 25 or 26 December (UTC)
  if extract(month from today) = 12 and extract(day from today) between 24 and 26 then perform games.passport_award(u, 'frogmas'); end if;
  -- Arcade Hopper: a score kept by the server in 5 different games
  games_played :=
      (case when exists (select 1 from games.yeet_records y where y.user_id = u and y.best > 0) then 1 else 0 end)
    + (case when exists (select 1 from games.wp_plays x where x.user_id = u and x.verified and x.guessed_at is not null) then 1 else 0 end)
    + (case when to_regclass('games.arcade_scores') is not null
              and exists (select 1 from games.arcade_scores a where a.user_id = u and a.game = 'fud') then 1 else 0 end)
    + (case when to_regclass('games.arcade_scores') is not null
              and exists (select 1 from games.arcade_scores a where a.user_id = u and a.game = 'snake') then 1 else 0 end)
    + (case when exists (select 1 from games.miner_saves s where s.user_id = u) then 1 else 0 end)
    + (case when exists (select 1 from games.results r join games.matches m on m.id = r.match_id
                          where r.user_id = u and r.verified and m.mode = 'obrazek') then 1 else 0 end)
    + (case when exists (select 1 from games.passport_badges b where b.user_id = u and b.badge_id = 'good_game') then 1 else 0 end);
  if games_played >= 5 then perform games.passport_award(u, 'arcade_hopper'); end if;
  -- Frog of the Week (the Weekly Champion) and Pond Dominator: from games.config.wp_hof_start on, the Hall of Fame
  -- settlement games.wp_settle() (update_wheres_pepe_hall_of_fame.sql) closes each day and week: exactly one first
  -- place wins, a tie has no winner, and leading alone all 7 days gives 'pond_dominator'. It marks the weeks it
  -- settles in passport_weeks, so the older rule below (every tied first place wins) only sees weeks before that.
  if to_regprocedure('games.wp_settle()') is not null then
    begin
      perform games.wp_settle();
    exception when others then
      raise warning 'passport wp settle hook: %', sqlerrm;
    end;
  end if;
  hof := (select (to_jsonb(c) ->> 'wp_hof_start')::date from games.config c where c.id = 1);
  if hof is null or wk < hof then
  insert into games.passport_weeks (week_start) values (wk) on conflict (week_start) do nothing;
  if found then
    for w in select z.user_id from (
        select x.user_id, rank() over (order by sum(x.points) desc) r
          from games.wp_plays x join games.wp_puzzles q on q.id = x.puzzle_id
         where x.verified and x.guessed_at is not null and q.day between wk and wk + 6
         group by x.user_id) z where z.r = 1 loop
      if games.discord_identity(w.user_id) is not null then
        insert into games.passport_badges (user_id, badge_id, earned_at, times) values (w.user_id, 'frog_of_the_week', clock_timestamp(), 1)
        on conflict (user_id, badge_id) do update set times = games.passport_badges.times + 1, earned_at = excluded.earned_at, notified_at = null;
      end if;
    end loop;
  end if;
  end if;
  -- Season Champion: first place of each finished ranked Pepe Pictures season (settled once, held once)
  for sn in select distinct m.season_no from games.matches m
             where m.ranked and m.mode = 'obrazek' and m.season_no is not null
               and (m.season_no < coalesce(cur, 0) or (m.season_no = cur and se->>'phase' = 'break'))
               and not exists (select 1 from games.passport_seasons p where p.season_no = m.season_no) loop
    insert into games.passport_seasons (season_no) values (sn) on conflict (season_no) do nothing;
    if found then
      for w in select z.uid from (
          select (array_agg(g.user_id))[1] uid, bool_or(g.verified) ver,
                 rank() over (order by sum(4 - g.place) desc, count(*) filter (where g.place = 1) desc,
                                       count(*) filter (where g.place = 2) desc, max(g.at) asc) r
            from games.guesses g join games.matches m on m.id = g.match_id
           where m.ranked and m.mode = 'obrazek' and m.season_no = sn
           group by case when g.verified then 'u:' || g.user_id::text else 'g:' || g.nick_key end) z
         where z.r = 1 and z.ver loop
        perform games.passport_award(w.uid, 'season_champion');
      end loop;
    end if;
  end loop;
end
$$;
revoke all on function games.passport_daily(uuid) from public, anon, authenticated;

create or replace function public.gry_passport_checkin()
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
  today date := (now() at time zone 'utc')::date;
  n integer;
  fresh jsonb;
begin
  if u is null or games.discord_identity(u) is null then
    return jsonb_build_object('signed_in', false);
  end if;
  insert into games.passport_days (user_id, day) values (u, today) on conflict (user_id, day) do nothing;
  if found then
    -- Welcome Back!: the first visit was yesterday, and this is the second one
    if (select count(*) from games.passport_days where user_id = u) = 2
       and exists (select 1 from games.passport_days where user_id = u and day = today - 1) then
      perform games.passport_award(u, 'welcome_back');
    end if;
    -- days are unique, so 14 rows in the last 14 days are 14 days in a row (and 30 in 30)
    select count(*) into n from games.passport_days where user_id = u and day > today - 14;
    if n >= 14 then perform games.passport_award(u, 'streak_14'); end if;
    select count(*) into n from games.passport_days where user_id = u and day > today - 30;
    if n >= 30 then perform games.passport_award(u, 'like_it_here'); end if;
  end if;
  -- the daily rules (Certified Fren, Old Frog, BALI, Frogmas, Arcade Hopper, Top 10, Frog of the Week, Season Champion)
  begin
    perform games.passport_daily(u);
  exception when others then
    raise warning 'passport daily hook: %', sqlerrm;
  end;
  -- Fresh Fren has its own notice in the Avatar Maker
  with shown as (
    update games.passport_badges b set notified_at = clock_timestamp()
     where b.user_id = u and b.notified_at is null and b.badge_id <> 'first_avatar'
    returning b.badge_id, b.earned_at)
  select coalesce(jsonb_agg(jsonb_build_object('id', badge_id, 'earned_at', earned_at) order by earned_at), '[]'::jsonb)
    into fresh from shown;
  return jsonb_build_object('signed_in', true, 'new_badges', fresh);
end
$$;
revoke all on function public.gry_passport_checkin() from public, anon, authenticated;
grant execute on function public.gry_passport_checkin() to authenticated;

-- ---------- Passport read path ----------
-- The newest definition (update_fren_avatar.sql had the previous one). Changes: Moonwalker is a stored
-- stamp now, and 'progress' carries the server's own counters for the Next Milestone bar.
create or replace function public.gry_passport_state()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
  d jsonb;
  joined timestamptz;
  best_distance integer := 0;
  extra_badges jsonb;
  discovered jsonb;
  owned_items jsonb;
  earned_count integer;
  badge_catalog jsonb;
  look jsonb;
  pr games.passport_progress%rowtype;
  login_streak integer := 0;
  day0 date := (now() at time zone 'utc')::date;
  progress jsonb;
begin
  -- Anonymous Supabase users also have auth.uid(). Require Discord specifically.
  if u is null then
    return jsonb_build_object('signed_in', false);
  end if;
  d := games.discord_identity(u);
  if d is null then
    return jsonb_build_object('signed_in', false);
  end if;

  select au.created_at into joined
    from auth.users au where au.id = u;

  select coalesce(y.best, 0) into best_distance
    from games.yeet_records y where y.user_id = u;
  best_distance := coalesce(best_distance, 0);

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', b.badge_id,
           'title', case b.badge_id when 'first_avatar' then 'Fresh Fren' else b.badge_id end,
           'description', 'Awarded by a PepecoinHub game',
           'earned_at', b.earned_at, 'times', b.times) order by b.earned_at), '[]'::jsonb)
    into extra_badges
    from games.passport_badges b where b.user_id = u and b.badge_id <> 'certified_fren';

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.secret_id, 'discovered_at', s.discovered_at)
           order by s.discovered_at), '[]'::jsonb)
    into discovered
    from games.passport_secrets s where s.user_id = u;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', i.item_id, 'quantity', i.quantity, 'earned_at', i.earned_at)
           order by i.earned_at), '[]'::jsonb)
    into owned_items
    from games.passport_items i where i.user_id = u;

  select jsonb_build_object('schema_version', a.schema_version,
           'bg', a.bg, 'clothing', a.clothing,
           'mouth', a.mouth, 'eyes', a.eyes, 'hat', a.hat, 'accessory', a.accessory, 'special', a.special)
    into look
    from games.passport_avatars a where a.user_id = u;

  select * into pr from games.passport_progress p where p.user_id = u;
  -- current run of PondOS days, ending today (or yesterday, before today's first visit)
  if not exists (select 1 from games.passport_days x where x.user_id = u and x.day = day0) then day0 := day0 - 1; end if;
  while login_streak < 400 and exists (select 1 from games.passport_days x where x.user_id = u and x.day = day0 - login_streak) loop
    login_streak := login_streak + 1;
  end loop;
  progress := jsonb_build_object(
    'yeet_5k_flights', (select count(*) from games.passport_yeet_5k f where f.user_id = u),
    'yeet_5k_total', coalesce(pr.yeet_5k_total, 0),
    'login_days', (select count(*) from games.passport_days x where x.user_id = u),
    'letters', coalesce(pr.letters, 0),
    'miner_minutes', coalesce(pr.miner_seconds, 0) / 60,
    'chat_days', (select count(*) from games.passport_chat_days c where c.user_id = u),
    'login_streak', login_streak,
    'wp_days', (select count(*) from games.wp_plays x join games.wp_puzzles q on q.id = x.puzzle_id
                 where x.user_id = u and x.verified and x.g_lat is not null and q.day is not null),
    'wp_perfect_days', (select count(*) from games.wp_plays x join games.wp_puzzles q on q.id = x.puzzle_id
                 where x.user_id = u and x.verified and x.g_lat is not null and x.points = 5000 and q.day is not null),
    'wp_streak', games.passport_wp_streak(u));

  badge_catalog := jsonb_build_array(
    jsonb_build_object('id', 'first_fren', 'title', 'First Fren',
      'description', 'Joined the pond with Discord.', 'earned_at', joined),
    jsonb_build_object('id', 'certified_fren', 'title', 'Certified Fren',
      'description', '100 distinct days of signed-in PondOS activity.',
      'earned_at', (select b.earned_at from games.passport_badges b
                    where b.user_id = u and b.badge_id = 'certified_fren'))
  );
  select count(*) into earned_count from jsonb_array_elements(badge_catalog) x
    where x->>'earned_at' is not null;
  earned_count := earned_count + jsonb_array_length(extra_badges);

  return jsonb_build_object(
    'signed_in', true,
    'nickname', coalesce(nullif(d->>'name', ''), 'Discord fren'),
    'member_since', joined,
    'yeet_best', best_distance,
    'achievements', badge_catalog || extra_badges,
    'achievements_earned', earned_count,
    'secrets', discovered,
    'items', owned_items,
    'avatar', look,
    'progress', progress,
    'care_days', null
  );
end
$$;
revoke all on function public.gry_passport_state() from public, anon, authenticated;
grant execute on function public.gry_passport_state() to authenticated;

-- internal helpers: never callable by the browser
revoke all on function games.passport_award(uuid, text, timestamptz), games.passport_yeet_flight(uuid, integer),
  games.passport_wp_check(uuid), games.passport_wp_streak(uuid), games.passport_wp_after(),
  games.passport_chat_after(), games.passport_mention_after(), games.passport_letter_after(),
  games.passport_miner_after() from public, anon, authenticated;

-- ---------- one-time work on the first run ----------
do $$
declare launch timestamptz; r record;
begin
  -- Pond Pioneer: every account with Discord linked right now. Never again after this run.
  insert into games.passport_meta (k) values ('pioneer_snapshot') on conflict (k) do nothing returning at into launch;
  if launch is not null then
    insert into games.passport_badges (user_id, badge_id, earned_at)
    select distinct i.user_id, 'pond_pioneer', launch
      from auth.identities i join auth.users au on au.id = i.user_id
     where i.provider = 'discord'
    on conflict (user_id, badge_id) do nothing;
  end if;
end $$;

-- Backfills from records the games already keep (safe to repeat: awards are on conflict do nothing).
-- Moonwalker: a 6000 m record, dated when it was flown.
select games.passport_award(y.user_id, 'moonwalker', y.achieved_at)
  from games.yeet_records y where y.best >= 60000;
-- Adept: a 3000 m record
select games.passport_award(y.user_id, 'yeet_adept', y.achieved_at)
  from games.yeet_records y where y.best >= 30000;
-- Podium: top 3 of a finished Pepe Pictures game
select games.passport_award(r.user_id, 'podium', r.finished_at)
  from games.results r join games.matches m on m.id = r.match_id where r.verified and r.place <= 3 and m.mode = 'obrazek';
-- Pepe Guesser: every Discord player with a verified play.
select games.passport_wp_check(p.user_id)
  from (select distinct x.user_id from games.wp_plays x where x.verified and x.g_lat is not null) p;
-- Letters: the server still has them (only read letters beyond the newest 2000 are ever deleted).
insert into games.passport_progress (user_id, letters)
select l.user_id, count(*) from games.letters l
  join auth.users au on au.id = l.user_id
 where l.discord group by l.user_id
on conflict (user_id) do nothing;
select games.passport_award(l.user_id, 'dear_editor', l.created_at)
  from (select user_id, created_at, row_number() over (partition by user_id order by created_at, id) as k
          from games.letters where discord) l
 where l.k = 1;
-- I Voted, FUD Buster, Long Snake, Secret Starter, Treasure Hunter: from records that already exist
do $$ begin
  if to_regclass('games.poll_votes') is not null then
    perform games.passport_award(v.user_id, 'i_voted', v.voted_at) from games.poll_votes v where v.verified;
  end if;
  if to_regclass('games.arcade_scores') is not null then
    perform games.passport_award(a.user_id, case a.game when 'fud' then 'fud_buster' else 'long_snake' end, a.created_at)
       from games.arcade_scores a
      where a.verified and a.user_id is not null and ((a.game = 'fud' and a.score >= 2000) or (a.game = 'snake' and a.score >= 40));
  end if;
end $$;
select games.passport_award(s.user_id, 'secret_starter') from (select distinct user_id from games.passport_secrets) s;
select games.passport_award(s.user_id, 'treasure_hunter') from (select user_id from games.passport_secrets group by user_id having count(*) >= 10) s;
-- Happy Mining!: everyone who already has a Pepe Miner cloud save.
select games.passport_award(m.user_id, 'rookie_miner') from games.miner_saves m;
-- Stamps retired or re-ruled by the v3 list (2026-11-08). The Passport is not public yet, so nothing
-- anyone has seen is removed; this only matters if an earlier draft of this file already ran.
-- Junior and Senior Editor once counted letters sent; now only "Printed" marks count.
delete from games.passport_badges b
 where b.badge_id in ('miner_fren', 'top_ten', 'the_secret_pond', 'bug_hunter')   -- Top 10 and The Secret Pond dropped by the owner, 2026-11-09
    or (b.badge_id = 'treasure_hunter' and (select count(*) from games.passport_secrets s where s.user_id = b.user_id) < 10)
    or (b.badge_id in ('junior_editor', 'senior_editor', 'vox_populi')
        and (select count(*) from games.passport_printed p where p.user_id = b.user_id)
            < case b.badge_id when 'junior_editor' then 1 when 'senior_editor' then 5 else 10 end);

-- ====================================================================================================
-- 12/17  update_passport_public.sql
-- ====================================================================================================
-- Fren Passport: look at another fren's passport (read only).
-- DRAFT. Apply to PH-games only after review, after update_fren_passport.sql and update_fren_avatar.sql.
-- update_passport_awards.sql can run before or after this file. Safe to run twice. It writes nothing.
--
-- Owner decisions (2026-11-08):
--   * Only players logged on with Discord can look, and only Discord players have a passport to look at
--     (guests and e-mail accounts have none).
--   * Everything the owner sees in their own booklet is public: the Fren (avatar), nickname, member since,
--     stamps with their dates, secrets with their dates, items and the best YEET flight. There is no switch
--     to hide a passport.
--   * Not shared: the counters behind the owner's Next Milestone bar (PondOS days and streak, chat days,
--     letters sent, Pepe Miner minutes, Pepe Guesser days and streak). They would show when someone is
--     around, and the letters and chat counters are kept off every screen on purpose. The Discord account
--     id and the e-mail address are never sent.
--   * A passport is found by its user id only (the LAN Party chat gets it with each verified message),
--     never by nickname, so nobody can walk the list of players.
--   * The browser UI stays behind /meme/?beta=fren until the owner opens the Passport to everyone.
--
-- The stamp list is the same one gry_passport_state() gives the owner: First Fren (Discord linked), every
-- stored stamp, and Moonwalker from the YEET record when the awards migration has not stored it yet.
-- 'times' is passed on when the badges table has that column (repeatable stamps, Frog of the Week).

create or replace function public.gry_passport_public(p_user uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
  d jsonb;
  pond_nick text;
  joined timestamptz;
  best_distance integer := 0;
  best_date timestamptz;
  stamps jsonb;
  discovered jsonb;
  owned_items jsonb;
  look jsonb;
begin
  -- the one looking: logged on with Discord (anonymous Supabase guests also have auth.uid())
  if u is null or games.discord_identity(u) is null then
    return jsonb_build_object('signed_in', false);
  end if;
  -- the one looked at: a Discord player
  d := games.discord_identity(p_user);
  if d is null then
    return jsonb_build_object('signed_in', true, 'found', false);
  end if;

  select au.created_at into joined from auth.users au where au.id = p_user;
  select p.nick into pond_nick from games.profiles p where p.user_id = p_user;

  select coalesce(y.best, 0), y.achieved_at into best_distance, best_date
    from games.yeet_records y where y.user_id = p_user;
  best_distance := coalesce(best_distance, 0);

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'id', b.badge_id,
           'title', case b.badge_id when 'first_avatar' then 'Fresh Fren' else b.badge_id end,
           'earned_at', b.earned_at,
           'times', to_jsonb(b) -> 'times')) order by b.earned_at), '[]'::jsonb)
    into stamps
    from games.passport_badges b where b.user_id = p_user;
  stamps := jsonb_build_array(jsonb_build_object('id', 'first_fren', 'title', 'First Fren', 'earned_at', joined)) || stamps;
  if best_distance >= 60000 and best_date is not null and not exists (
       select 1 from games.passport_badges b where b.user_id = p_user and b.badge_id = 'moonwalker') then
    stamps := stamps || jsonb_build_array(jsonb_build_object('id', 'moonwalker', 'title', 'Moonwalker', 'earned_at', best_date));
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.secret_id, 'discovered_at', s.discovered_at) order by s.discovered_at), '[]'::jsonb)
    into discovered
    from games.passport_secrets s where s.user_id = p_user;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', i.item_id, 'quantity', i.quantity, 'earned_at', i.earned_at) order by i.earned_at), '[]'::jsonb)
    into owned_items
    from games.passport_items i where i.user_id = p_user;

  select jsonb_build_object('schema_version', a.schema_version,
           'bg', a.bg, 'clothing', a.clothing,
           'mouth', a.mouth, 'eyes', a.eyes, 'hat', a.hat, 'accessory', a.accessory, 'special', a.special)
    into look
    from games.passport_avatars a where a.user_id = p_user;

  return jsonb_build_object(
    'signed_in', true,
    'found', true,
    'user_id', p_user,
    'nickname', coalesce(nullif(d->>'name', ''), 'Discord fren'),
    'nick', pond_nick,
    'member_since', joined,
    'yeet_best', best_distance,
    'achievements', stamps,
    'achievements_earned', (select count(*) from jsonb_array_elements(stamps) x where x->>'earned_at' is not null),
    'secrets', discovered,
    'items', owned_items,
    'avatar', look
  );
end
$$;

revoke all on function public.gry_passport_public(uuid) from public, anon, authenticated;
grant execute on function public.gry_passport_public(uuid) to authenticated;

-- ====================================================================================================
-- 13/17  update_pepegochi_v2.sql
-- ====================================================================================================
-- PepeGochi v2: one personal frog at a time per Discord account. A frog can move out after
-- neglect (it is never shown dying), leaves GOODBYE.TXT, and the owner can adopt a new one.
-- Past lives stay as history.
--
-- DRAFT (PR A1). Not applied anywhere. Test on a local database or a separate staging project only.
-- Do NOT run in the production SQL editor without the owner's explicit approval.
--
-- Design: docs/design/pepegochi-v2/ (README.md, TECH_PLAN.md). Browser contract: games/PEPEGOCHI_API.md.
-- Supersedes the v1 draft in PR #186, which was never applied (owner check of PH-games, 2026-11-07).
--
-- Trust rules:
--  * The database owns time, needs, growth, care days, departure and history. The browser sends only a
--    pet name or one of four action names: no user id, stat, count, time or stamp id.
--  * Discord accounts only (games.discord_identity). Private tables in schema games, RLS on, no grants.
--  * Every write locks the owner's row first, then the newest life; server time is read after the locks.
--  * No cron, Realtime, heartbeat or click log. A frog that moved out is written once, by the next write
--    call. The moment it left is computed from saved timestamps, so it never depends on when that is.
--  * Moving out deletes nothing: stamps, items, avatars and secrets are not touched by this file.
--  * Stamps are not written here. Milestones go to games.pepegochi_milestones in the same transaction as
--    the care action. A separate, isolated hook hands them to the Fren Passport later (PR C). If the hook
--    fails, the care is kept and the milestone stays pending, so it can still be awarded later.
--
-- Values in games.pepegochi_rules() are PLAYTEST values, not final rules.
--
-- Dependency: PH-games schema.sql (games.discord_identity). Independent of the Fren Passport files.
-- Safe to run twice.

-- v2 starts from a clean schema. Never run it on top of v1 data by accident.
do $$
begin
  if to_regclass('games.pepegochi_pets') is not null then
    raise exception 'games.pepegochi_pets (PepeGochi v1) exists. Move its pets to v2 by hand before running this file.';
  end if;
end $$;

-- ---------- storage ----------
-- One row per account: the lock for adopting and moving out.
create table if not exists games.pepegochi_owners (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null
);

-- One row per frog life. After the frog moves out, the same row is its history entry.
create table if not exists games.pepegochi_lives (
  life_id     uuid primary key default gen_random_uuid(),
  user_id     uuid not null references games.pepegochi_owners(user_id) on delete cascade,
  generation  integer not null check (generation between 1 and 100000),
  pet_name    text not null check (char_length(pet_name) between 2 and 18 and pet_name ~ '^[[:alnum:] _.-]+$'),
  adopted_at  timestamptz not null,
  -- needs as saved by the last accepted action (needs_at); reads derive the current values
  hunger      numeric(7,4) not null default 75 check (hunger between 0 and 100),
  hygiene     numeric(7,4) not null default 80 check (hygiene between 0 and 100),
  mood        numeric(7,4) not null default 80 check (mood between 0 and 100),
  energy      numeric(7,4) not null default 75 check (energy between 0 and 100),
  needs_at    timestamptz not null,
  -- growth: distinct UTC days with at least one accepted action
  care_days         integer not null default 0 check (care_days between 0 and 100000),
  last_care_day_utc date,
  -- each need's own clock: the moment it started waiting for care (null = adopted_at). A need that is
  -- cared for, or still at/above meaningful_below, is not waiting; a future value means "fine until then".
  hunger_due_at  timestamptz,
  hygiene_due_at timestamptz,
  mood_due_at    timestamptz,
  energy_due_at  timestamptz,
  -- last accepted action of each kind (cooldowns)
  last_feed_at   timestamptz,
  last_clean_at  timestamptz,
  last_play_at   timestamptz,
  last_rest_at   timestamptz,
  last_action_at timestamptz,
  -- rescue: the frog reached "packing"; caring for every overdue need then starts recovery
  rescue_pending     boolean not null default false,
  recovery_days_left smallint not null default 0 check (recovery_days_left between 0 and 30),
  recovery_day_utc   date,
  recovery_since     timestamptz,   -- when the last recovery step counted (check-up or follow-up)
  -- accepted actions per UTC day, kept in this row (no request log)
  action_day_utc date,
  actions_today  integer not null default 0 check (actions_today between 0 and 1000),
  -- good care days (PR A2): which kinds of care were given on action_day_utc (1 feed, 2 clean, 4 play, 8 rest)
  day_kinds         smallint not null default 0 check (day_kinds between 0 and 15),
  good_days         integer not null default 0 check (good_days >= 0),
  last_good_day_utc date,
  good_streak       integer not null default 0 check (good_streak >= 0),   -- good days in a row, up to the last one
  best_good_streak  integer not null default 0 check (best_good_streak >= 0),
  -- totals for future goodbye-letter variants (they cannot be rebuilt later)
  feeds  integer not null default 0 check (feeds >= 0),
  cleans integer not null default 0 check (cleans >= 0),
  plays  integer not null default 0 check (plays >= 0),
  rests  integer not null default 0 check (rests >= 0),
  -- end of life, written once
  status           text not null default 'active' check (status in ('active', 'departed')),
  departed_at      timestamptz,
  departure_reason text check (departure_reason in ('feed', 'clean', 'play', 'rest', 'recovery')),
  letter_variant   text check (letter_variant ~ '^[a-z_]{3,24}$'),
  letter_seen_at   timestamptz,
  unique (user_id, generation),
  check ((status = 'departed') = (departed_at is not null)),
  check (letter_seen_at is null or status = 'departed')
);
-- a local or staging database that already ran the A1 version of this file gets the good-day columns
alter table games.pepegochi_lives
  add column if not exists day_kinds smallint not null default 0 check (day_kinds between 0 and 15),
  add column if not exists good_days integer not null default 0 check (good_days >= 0),
  add column if not exists last_good_day_utc date,
  add column if not exists good_streak integer not null default 0 check (good_streak >= 0),
  add column if not exists best_good_streak integer not null default 0 check (best_good_streak >= 0);
-- exactly one active frog per account, enforced by the database
create unique index if not exists pepegochi_one_active_life
  on games.pepegochi_lives (user_id) where status = 'active';

-- Account milestones the server has seen (first adoption, froglet, adult, good parent). Written in the same
-- transaction as the action. synced_at stays null until the Passport hook has delivered the stamp.
create table if not exists games.pepegochi_milestones (
  user_id    uuid not null references games.pepegochi_owners(user_id) on delete cascade,
  milestone  text not null check (milestone ~ '^[a-z0-9_]{3,40}$'),
  life_id    uuid not null references games.pepegochi_lives(life_id) on delete cascade,
  reached_at timestamptz not null,
  synced_at  timestamptz,
  primary key (user_id, milestone)
);
create index if not exists pepegochi_milestones_pending
  on games.pepegochi_milestones (user_id) where synced_at is null;

alter table games.pepegochi_owners enable row level security;
alter table games.pepegochi_lives enable row level security;
alter table games.pepegochi_milestones enable row level security;
revoke all on games.pepegochi_owners, games.pepegochi_lives, games.pepegochi_milestones
  from public, anon, authenticated;

-- ---------- time and rules ----------
-- Server time for every PepeGochi rule. Tests and scripts/pepegochi_sim.mjs replace this function in
-- their own throwaway database to fast-forward time. Here the body must stay exactly clock_timestamp()
-- (tests/pepegochi.test.mjs checks it).
create or replace function games.pepegochi_clock()
returns timestamptz language sql volatile set search_path = '' as $$
  select clock_timestamp()
$$;

-- PLAYTEST values (owner, 2026-11-07): working numbers to tune, not final rules.
-- The state RPC returns them, so the game always explains the rules the server really uses.
create or replace function games.pepegochi_rules()
returns jsonb language sql stable set search_path = '' as $$
  select jsonb_build_object(
    'version', 2,
    'playtest', true,
    'meaningful_below', 90,       -- an action is accepted only while its need is below this
    'neglected_h', 48,            -- the most neglected need has waited this long: neglected
    'packing_h', 120,             -- ... packing: "Your Fren is thinking of leaving"
    'departs_h', 168,             -- ... the frog moves out
    'rescue_from_h', 120,         -- caring again for a frog that reached this starts recovery
    'recovery_days', 1,           -- later UTC days with care needed to finish recovery (owner: 1, so
                                  -- Saturday + Sunday players can keep their frog)
    'recovery_departs_h', 72,     -- while recovering, the frog moves out after this long without care
    'recovery_min_gap_h', 8,      -- owner, 2026-11-07: the next-day visit counts only 8 h after the check-up,
                                  -- so one session across UTC midnight cannot count as two days
    'max_actions_per_utc_day', 12,
    'min_gap_s', 2,
    'cooldown_min', jsonb_build_object('feed', 30, 'clean', 20, 'play', 45, 'rest', 60),
    'decay_per_day', jsonb_build_object('hunger', 20, 'hygiene', 15, 'mood', 18, 'energy', 10),
    'froglet_care_days', 2,
    'adult_care_days', 7,
    -- good care days (PR A2), PLAYTEST: at most one per UTC day
    'good_day_min_kinds', 2,      -- different kinds of care on that UTC day
    'good_day_min_need', 40,      -- owner, 2026-11-07: every need at least this after the action that completes the day
    'good_day_cared_counts', false, -- proposal, off: a need cared for that day counts as fine below min_need
    'good_parent_days', 30,       -- owner, working value: good days in one life, not necessarily in a row
    'history_limit', 10
  )
$$;

-- ---------- derived state (no writes) ----------
-- Time arithmetic is exact on purpose (docs/games/js/pepegochi-model.mjs must give the same answers):
-- decay multiplies before its single division, and computed moments are rounded to whole microseconds.
-- Never add day-sized intervals: in a session time zone with daylight saving time they move by an hour.
--
-- When a need starts waiting for care, after an accepted action at time t left it at value v:
-- at/above the threshold it is fine until linear decay takes it below; cared for just now it waits
-- from t; otherwise it keeps waiting since it was last fine.
create or replace function games.pepegochi_due(
  v numeric, prev timestamptz, t timestamptz, acted boolean, per_day numeric, threshold numeric)
returns timestamptz language sql immutable set search_path = '' as $$
  select case
    when v >= threshold then
      case when per_day > 0
           then t + round((v - threshold) * 86400000000 / per_day)::bigint * interval '1 microsecond'
           else 'infinity'::timestamptz end
    when acted then t
    else least(prev, t)
  end
$$;

-- Current needs, the most neglected need, the departure moment and the status of one life at time t.
-- A life that already moved out is frozen at the moment it left.
create or replace function games.pepegochi_eval(
  l games.pepegochi_lives, t timestamptz, r jsonb,
  out hunger numeric, out hygiene numeric, out mood numeric, out energy numeric,
  out oldest_kind text, out oldest_at timestamptz, out care_at timestamptz,
  out departs_at timestamptz, out departure_reason text, out status text)
language plpgsql stable set search_path = '' as $$
declare
  feed_at  timestamptz := coalesce(l.hunger_due_at, l.adopted_at);
  clean_at timestamptz := coalesce(l.hygiene_due_at, l.adopted_at);
  play_at  timestamptz := coalesce(l.mood_due_at, l.adopted_at);
  rest_at  timestamptz := coalesce(l.energy_due_at, l.adopted_at);
  by_recovery timestamptz;
  secs numeric;
  age_h numeric;
  idle_h numeric;
begin
  oldest_kind := 'feed'; oldest_at := feed_at;
  if clean_at < oldest_at then oldest_kind := 'clean'; oldest_at := clean_at; end if;
  if play_at < oldest_at then oldest_kind := 'play'; oldest_at := play_at; end if;
  if rest_at < oldest_at then oldest_kind := 'rest'; oldest_at := rest_at; end if;
  -- every accepted action is a meaningful one, so the last action is the last care
  care_at := coalesce(l.last_action_at, l.adopted_at);

  if l.status = 'departed' then
    hunger := l.hunger; hygiene := l.hygiene; mood := l.mood; energy := l.energy;
    departs_at := l.departed_at; departure_reason := l.departure_reason; status := 'departed';
    return;
  end if;

  -- any need left alone for departs_h; while recovering, also no care at all for recovery_departs_h
  departs_at := oldest_at + (r->>'departs_h')::numeric * interval '1 hour';
  departure_reason := oldest_kind;
  if l.recovery_days_left > 0 then
    by_recovery := care_at + (r->>'recovery_departs_h')::numeric * interval '1 hour';
    if by_recovery < departs_at then departs_at := by_recovery; departure_reason := 'recovery'; end if;
  end if;

  -- needs fall linearly until the frog leaves, never below 0
  secs := greatest(0::numeric, extract(epoch from (least(t, departs_at) - l.needs_at)));
  hunger  := greatest(0::numeric, l.hunger  - secs * (r#>>'{decay_per_day,hunger}')::numeric / 86400);
  hygiene := greatest(0::numeric, l.hygiene - secs * (r#>>'{decay_per_day,hygiene}')::numeric / 86400);
  mood    := greatest(0::numeric, l.mood    - secs * (r#>>'{decay_per_day,mood}')::numeric / 86400);
  energy  := greatest(0::numeric, l.energy  - secs * (r#>>'{decay_per_day,energy}')::numeric / 86400);

  age_h := extract(epoch from (t - oldest_at)) / 3600;
  idle_h := extract(epoch from (t - care_at)) / 3600;
  if t >= departs_at then
    status := 'departed';
  elsif l.recovery_days_left > 0 then
    status := case when idle_h >= (r->>'neglected_h')::numeric then 'packing' else 'recovering' end;
  elsif age_h >= (r->>'packing_h')::numeric then
    status := 'packing';
  elsif age_h >= (r->>'neglected_h')::numeric then
    status := 'neglected';
  else
    status := 'healthy';
  end if;
end
$$;

-- The full state the browser gets back from every RPC, for one account at time t. Read-only.
create or replace function games.pepegochi_view(u uuid, t timestamptz)
returns jsonb language plpgsql stable set search_path = '' as $$
declare
  r jsonb := games.pepegochi_rules();
  l games.pepegochi_lives%rowtype;
  e record;
  pet jsonb;
  hist jsonb;
  former integer;
  longest integer;
  first_left timestamptz;
  departed boolean;
  stage text;
  age_h numeric;
  overdue jsonb;
  today integer;
  kinds_today integer;
  low jsonb;
  mn numeric := (r->>'good_day_min_need')::numeric;
  cared boolean := (r->>'good_day_cared_counts')::boolean;
  day_utc date := (t at time zone 'UTC')::date;
begin
  select * into l from games.pepegochi_lives x where x.user_id = u order by x.generation desc limit 1;
  if not found then
    return jsonb_build_object('version', 2, 'server_now', t, 'rules', r,
      'has_pet', false, 'can_adopt', true, 'pet', null, 'history', '[]'::jsonb,
      'summary', jsonb_build_object('frens_adopted', 0, 'former_frens', 0,
                                    'longest_friendship_days', 0, 'first_departed_at', null));
  end if;

  e := games.pepegochi_eval(l, t, r);
  departed := e.status = 'departed';
  -- a new frog is an egg until its first accepted care (owner, 2026-11-09), then a tadpole
  stage := case when l.care_days >= (r->>'adult_care_days')::integer then 'adult'
                when l.care_days >= (r->>'froglet_care_days')::integer then 'froglet'
                when l.care_days >= 1 then 'tadpole'
                else 'egg' end;

  if departed then
    pet := jsonb_build_object(
      'life_id', l.life_id, 'generation', l.generation, 'name', l.pet_name, 'adopted_at', l.adopted_at,
      'stage', stage, 'care_days', l.care_days,
      'status', 'departed',
      'departed_at', e.departs_at,
      'departure_saved', l.status = 'departed',
      'departure_reason', e.departure_reason,
      'days_together', floor(extract(epoch from (e.departs_at - l.adopted_at)) / 86400)::integer,
      'good_days', l.good_days, 'best_good_streak', l.best_good_streak,
      'letter', jsonb_build_object('variant', coalesce(l.letter_variant, 'classic'),
                                   'seen', l.letter_seen_at is not null));
  else
    age_h := extract(epoch from (t - e.oldest_at)) / 3600;
    -- the needs a check-up still has to cover (empty while recovering)
    select coalesce(jsonb_agg(v.k order by v.n), '[]'::jsonb) into overdue
      from (values (1, 'feed', coalesce(l.hunger_due_at, l.adopted_at)),
                   (2, 'clean', coalesce(l.hygiene_due_at, l.adopted_at)),
                   (3, 'play', coalesce(l.mood_due_at, l.adopted_at)),
                   (4, 'rest', coalesce(l.energy_due_at, l.adopted_at))) v(n, k, since)
     where l.recovery_days_left = 0
       and extract(epoch from (t - v.since)) / 3600 >= (r->>'neglected_h')::numeric;
    today := case when l.action_day_utc = day_utc then l.actions_today else 0 end;
    kinds_today := case when l.action_day_utc = day_utc then l.day_kinds else 0 end;
    -- the needs that would stop a good day right now
    select coalesce(jsonb_agg(v.k order by v.n), '[]'::jsonb) into low
      from (values (1, 'feed', e.hunger, 1), (2, 'clean', e.hygiene, 2),
                   (3, 'play', e.mood, 4), (4, 'rest', e.energy, 8)) v(n, k, val, b)
     where v.val < mn and not (cared and (kinds_today & v.b) <> 0);
    pet := jsonb_build_object(
      'life_id', l.life_id, 'generation', l.generation, 'name', l.pet_name, 'adopted_at', l.adopted_at,
      'life_day', floor(extract(epoch from (t - l.adopted_at)) / 86400)::integer + 1,
      'stage', stage,
      'next_growth_care_days', case stage when 'egg' then 1 when 'tadpole' then (r->>'froglet_care_days')::integer
                                          when 'froglet' then (r->>'adult_care_days')::integer end,
      'care_days', l.care_days,
      'last_care_day_utc', l.last_care_day_utc,
      'status', e.status,
      'needs', jsonb_build_object('hunger', floor(e.hunger)::integer, 'hygiene', floor(e.hygiene)::integer,
                                  'mood', floor(e.mood)::integer, 'energy', floor(e.energy)::integer),
      -- when each need started (or will start) waiting for care
      'waiting_since', jsonb_build_object('feed', coalesce(l.hunger_due_at, l.adopted_at),
                                          'clean', coalesce(l.hygiene_due_at, l.adopted_at),
                                          'play', coalesce(l.mood_due_at, l.adopted_at),
                                          'rest', coalesce(l.energy_due_at, l.adopted_at)),
      'most_neglected', e.oldest_kind,
      'most_neglected_since', e.oldest_at,
      'overdue', overdue,
      'rescue_starts_recovery', l.recovery_days_left = 0
                                and (l.rescue_pending or age_h >= (r->>'rescue_from_h')::numeric),
      'recovery', case when l.recovery_days_left > 0 then
                    jsonb_build_object('days_left', l.recovery_days_left, 'last_day_utc', l.recovery_day_utc,
                      -- the earliest moment the next visit counts: a later UTC day (and the gap, if set)
                      'counts_from', greatest(((l.recovery_day_utc + 1)::timestamp at time zone 'UTC'),
                                              l.recovery_since + (r->>'recovery_min_gap_h')::numeric * interval '1 hour')) end,
      'departs_at', e.departs_at,
      'departure_reason', e.departure_reason,
      'cooldowns', jsonb_build_object(
        'feed',  l.last_feed_at  + (r#>>'{cooldown_min,feed}')::numeric  * interval '1 minute',
        'clean', l.last_clean_at + (r#>>'{cooldown_min,clean}')::numeric * interval '1 minute',
        'play',  l.last_play_at  + (r#>>'{cooldown_min,play}')::numeric  * interval '1 minute',
        'rest',  l.last_rest_at  + (r#>>'{cooldown_min,rest}')::numeric  * interval '1 minute',
        'any_action', l.last_action_at + (r->>'min_gap_s')::numeric * interval '1 second'),
      'action_budget', jsonb_build_object('accepted_today', today,
                                          'max_per_utc_day', (r->>'max_actions_per_utc_day')::integer),
      -- good care days (PR A2) and the Good Parent goal (good days in this life, not necessarily in a row)
      'good_days', l.good_days,
      'good_days_goal', (r->>'good_parent_days')::integer,
      'good_streak', case when l.last_good_day_utc >= day_utc - 1 then l.good_streak else 0 end,
      'best_good_streak', l.best_good_streak,
      'good_day', jsonb_build_object(
        'today', coalesce(l.last_good_day_utc = day_utc, false),
        'kinds_today', (kinds_today & 1) + ((kinds_today >> 1) & 1) + ((kinds_today >> 2) & 1) + ((kinds_today >> 3) & 1),
        'needs_low', low));
  end if;

  -- earlier lives: all of them have moved out (a new life is only adopted after that)
  select coalesce(jsonb_agg(jsonb_build_object(
           'generation', h.generation, 'name', h.pet_name,
           'adopted_at', h.adopted_at, 'departed_at', h.departed_at,
           'days_together', floor(extract(epoch from (h.departed_at - h.adopted_at)) / 86400)::integer,
           'care_days', h.care_days, 'departure_reason', h.departure_reason,
           'good_days', h.good_days, 'best_good_streak', h.best_good_streak)
           order by h.generation desc), '[]'::jsonb)
    into hist
    from (select * from games.pepegochi_lives x
           where x.user_id = u and x.generation < l.generation
           order by x.generation desc limit (r->>'history_limit')::integer) h;
  select count(*), coalesce(max(floor(extract(epoch from (x.departed_at - x.adopted_at)) / 86400)), 0),
         min(x.departed_at)
    into former, longest, first_left
    from games.pepegochi_lives x where x.user_id = u and x.generation < l.generation;
  if departed then
    former := former + 1;
    first_left := least(first_left, e.departs_at);
  end if;
  longest := greatest(longest,
    floor(extract(epoch from ((case when departed then e.departs_at else t end) - l.adopted_at)) / 86400)::integer);

  return jsonb_build_object('version', 2, 'server_now', t, 'rules', r,
    'has_pet', not departed,
    'can_adopt', departed and l.letter_seen_at is not null,
    'pet', pet, 'history', hist,
    'summary', jsonb_build_object('frens_adopted', l.generation, 'former_frens', former,
                                  'longest_friendship_days', longest, 'first_departed_at', first_left));
end
$$;

-- ---------- internal writes ----------
-- Writes "moved out" once, if the frog is due to leave at time t. Returns true when it wrote.
-- departed_at is the computed moment, not t, so the result never depends on when this runs.
create or replace function games.pepegochi_settle(l games.pepegochi_lives, t timestamptz, r jsonb)
returns boolean language plpgsql volatile set search_path = '' as $$
declare
  e record;
begin
  if l.status <> 'active' then return false; end if;
  e := games.pepegochi_eval(l, t, r);
  if e.status <> 'departed' then return false; end if;
  update games.pepegochi_lives set
    status = 'departed', departed_at = e.departs_at, departure_reason = e.departure_reason,
    letter_variant = 'classic',
    hunger = e.hunger, hygiene = e.hygiene, mood = e.mood, energy = e.energy, needs_at = e.departs_at
  where life_id = l.life_id and status = 'active';
  return found;
end
$$;

-- Records an account milestone once (first_adoption, hatched, froglet, adult, good_parent). Never a stamp by itself.
create or replace function games.pepegochi_milestone(u uuid, m text, life uuid, p_at timestamptz)
returns void language plpgsql volatile set search_path = '' as $$
begin
  if m not in ('first_adoption', 'hatched', 'froglet', 'adult', 'good_parent') then
    raise exception 'Unknown PepeGochi milestone %', m;
  end if;
  insert into games.pepegochi_milestones (user_id, milestone, life_id, reached_at)
  values (u, m, life, p_at)
  on conflict (user_id, milestone) do nothing;
end
$$;

-- The Passport hook. Created here only when it does not exist yet, so re-running this file never
-- switches off a real hook installed later by the Passport bridge (PR C).
do $$
begin
  if to_regprocedure('games.pepegochi_passport_sync(uuid)') is null then
    create function games.pepegochi_passport_sync(u uuid)
    returns void language plpgsql volatile set search_path = '' as $f$
    begin
      -- No-op until the Fren Passport bridge (PR C) replaces it. Milestones wait in
      -- games.pepegochi_milestones with synced_at = null, so the bridge can still award them.
      return;
    end
    $f$;
  end if;
end $$;

-- Hands pending milestones to the Passport hook. A failing hook is logged as a warning and never
-- undoes the care action; the milestone stays pending and is retried on the next accepted write.
create or replace function games.pepegochi_sync(u uuid)
returns void language plpgsql volatile set search_path = '' as $$
begin
  if exists (select 1 from games.pepegochi_milestones m where m.user_id = u and m.synced_at is null) then
    begin
      perform games.pepegochi_passport_sync(u);
    exception when others then
      raise warning 'pepegochi passport sync: %', sqlerrm;
    end;
  end if;
end
$$;

revoke all on function games.pepegochi_clock(), games.pepegochi_rules(),
  games.pepegochi_due(numeric, timestamptz, timestamptz, boolean, numeric, numeric),
  games.pepegochi_eval(games.pepegochi_lives, timestamptz, jsonb), games.pepegochi_view(uuid, timestamptz),
  games.pepegochi_settle(games.pepegochi_lives, timestamptz, jsonb),
  games.pepegochi_milestone(uuid, text, uuid, timestamptz), games.pepegochi_passport_sync(uuid),
  games.pepegochi_sync(uuid)
  from public, anon, authenticated;

-- ---------- browser RPCs (Discord only, no user id) ----------
-- Read-only, even when the frog is due to move out: that is written by the next write call.
create or replace function public.gry_pepegochi_state()
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
begin
  if u is null or games.discord_identity(u) is null then
    raise exception 'Discord sign-in required' using errcode = '42501';
  end if;
  return games.pepegochi_view(u, games.pepegochi_clock());
end
$$;
revoke all on function public.gry_pepegochi_state() from public, anon, authenticated;
grant execute on function public.gry_pepegochi_state() to authenticated;

-- Adopts a frog when there is none, or after the previous one moved out and its letter was read.
-- With an active frog it returns that frog: a frog cannot be replaced.
create or replace function public.gry_pepegochi_adopt(p_name text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
  r jsonb := games.pepegochi_rules();
  cleaned text;
  t timestamptz;
  l games.pepegochi_lives%rowtype;
  had_life boolean;
  new_life uuid;
begin
  if u is null or games.discord_identity(u) is null then
    raise exception 'Discord sign-in required' using errcode = '42501';
  end if;
  cleaned := btrim(left(coalesce(p_name, ''), 64));
  if char_length(coalesce(p_name, '')) > 64 or char_length(cleaned) not between 2 and 18
     or cleaned !~ '^[[:alnum:] _.-]+$' then
    raise exception 'Name must be 2-18 letters, numbers, spaces, dots, dashes or underscores'
      using errcode = '22023';
  end if;

  insert into games.pepegochi_owners (user_id, created_at) values (u, games.pepegochi_clock())
  on conflict (user_id) do nothing;
  perform 1 from games.pepegochi_owners o where o.user_id = u for update;
  select * into l from games.pepegochi_lives x where x.user_id = u
    order by x.generation desc limit 1 for update;
  had_life := found;
  t := games.pepegochi_clock();

  if had_life then
    if l.status = 'active' then
      if not games.pepegochi_settle(l, t, r) then
        return games.pepegochi_view(u, t) || jsonb_build_object('adopt_result', 'already_have_fren');
      end if;
      -- it has just moved out; the owner sees the letter before a new egg
      return games.pepegochi_view(u, t) || jsonb_build_object('adopt_result', 'read_the_letter_first');
    end if;
    if l.letter_seen_at is null then
      return games.pepegochi_view(u, t) || jsonb_build_object('adopt_result', 'read_the_letter_first');
    end if;
  end if;

  insert into games.pepegochi_lives (user_id, generation, pet_name, adopted_at, needs_at)
  values (u, coalesce(l.generation, 0) + 1, cleaned, t, t)
  returning life_id into new_life;
  perform games.pepegochi_milestone(u, 'first_adoption', new_life, t);
  perform games.pepegochi_sync(u);
  return games.pepegochi_view(u, t) || jsonb_build_object('adopt_result', 'adopted');
end
$$;
revoke all on function public.gry_pepegochi_adopt(text) from public, anon, authenticated;
grant execute on function public.gry_pepegochi_adopt(text) to authenticated;

-- One of four care actions. Rejections raise an error and write nothing. A frog that is due to move
-- out is written as moved out instead (action_result = 'moved_out'); the action is not applied.
create or replace function public.gry_pepegochi_action(p_action text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
  r jsonb := games.pepegochi_rules();
  t timestamptz;
  day_utc date;
  l games.pepegochi_lives%rowtype;
  e record;
  has_owner boolean;
  today_count integer;
  last_kind timestamptz;
  need_now numeric;
  h numeric; c numeric; m numeric; en numeric;
  thr numeric;
  due_h timestamptz; due_c timestamptz; due_m timestamptz; due_e timestamptz;
  new_oldest timestamptz;
  was_age_h numeric;
  new_care_day boolean;
  rescue boolean;
  rec_left smallint;
  rec_day date;
  rec_since timestamptz;
  kinds integer;
  mn numeric;
  cared boolean;
  good_now boolean := false;
  g_days integer; g_last date; g_streak integer; g_best integer;
begin
  if u is null or games.discord_identity(u) is null then
    raise exception 'Discord sign-in required' using errcode = '42501';
  end if;
  if p_action is null or p_action not in ('feed', 'clean', 'play', 'rest') then
    raise exception 'Unknown care action' using errcode = '22023';
  end if;

  select true into has_owner from games.pepegochi_owners o where o.user_id = u for update;
  if has_owner is null then
    raise exception 'Adopt a Fren first' using errcode = 'P0001';
  end if;
  select * into l from games.pepegochi_lives x where x.user_id = u
    order by x.generation desc limit 1 for update;
  t := games.pepegochi_clock();   -- after the locks
  if l.status is distinct from 'active' then
    return games.pepegochi_view(u, t) || jsonb_build_object('action_result', 'moved_out');
  end if;

  e := games.pepegochi_eval(l, t, r);
  if e.status = 'departed' then
    perform games.pepegochi_settle(l, t, r);
    return games.pepegochi_view(u, t) || jsonb_build_object('action_result', 'moved_out');
  end if;

  day_utc := (t at time zone 'UTC')::date;
  today_count := case when l.action_day_utc = day_utc then l.actions_today else 0 end;
  if l.last_action_at is not null
     and t < l.last_action_at + (r->>'min_gap_s')::numeric * interval '1 second' then
    raise exception 'Wait a moment before the next care action' using errcode = 'P0001';
  end if;
  if today_count >= (r->>'max_actions_per_utc_day')::integer then
    raise exception 'Daily care action limit reached' using errcode = 'P0001';
  end if;
  last_kind := case p_action when 'feed' then l.last_feed_at when 'clean' then l.last_clean_at
                             when 'play' then l.last_play_at else l.last_rest_at end;
  if last_kind is not null
     and t < last_kind + (r#>>array['cooldown_min', p_action])::numeric * interval '1 minute' then
    raise exception 'That action is cooling down' using errcode = 'P0001';
  end if;
  need_now := case p_action when 'feed' then e.hunger when 'clean' then e.hygiene
                            when 'play' then e.mood else e.energy end;
  if need_now >= (r->>'meaningful_below')::numeric then
    raise exception 'Your Fren does not need that right now' using errcode = 'P0001';
  end if;

  -- effects, as in v1; fractions are kept, only the response is rounded
  h := e.hunger; c := e.hygiene; m := e.mood; en := e.energy;
  if p_action = 'feed' then
    h := least(100::numeric, h + 35);
  elsif p_action = 'clean' then
    c := least(100::numeric, c + 40);
  elsif p_action = 'play' then
    m := least(100::numeric, m + 35);
    en := greatest(0::numeric, en - 10);
    h := greatest(0::numeric, h - 3);
  else
    en := least(100::numeric, en + 40);
    m := least(100::numeric, m + 5);
  end if;

  -- each need's clock after this action
  thr := (r->>'meaningful_below')::numeric;
  due_h := games.pepegochi_due(h, coalesce(l.hunger_due_at, l.adopted_at), t, p_action = 'feed',
                               (r#>>'{decay_per_day,hunger}')::numeric, thr);
  due_c := games.pepegochi_due(c, coalesce(l.hygiene_due_at, l.adopted_at), t, p_action = 'clean',
                               (r#>>'{decay_per_day,hygiene}')::numeric, thr);
  due_m := games.pepegochi_due(m, coalesce(l.mood_due_at, l.adopted_at), t, p_action = 'play',
                               (r#>>'{decay_per_day,mood}')::numeric, thr);
  due_e := games.pepegochi_due(en, coalesce(l.energy_due_at, l.adopted_at), t, p_action = 'rest',
                               (r#>>'{decay_per_day,energy}')::numeric, thr);

  -- rescue and recovery
  new_oldest := least(due_h, due_c, due_m, due_e);
  was_age_h := extract(epoch from (t - e.oldest_at)) / 3600;
  new_care_day := l.last_care_day_utc is distinct from day_utc;
  rescue := l.rescue_pending;
  rec_left := l.recovery_days_left;
  rec_day := l.recovery_day_utc;
  rec_since := l.recovery_since;
  if rec_left > 0 then
    -- recovering: each later UTC day with care counts once (and, if set, only after the minimum gap)
    if (rec_day is null or day_utc > rec_day)
       and (rec_since is null
            or t >= rec_since + (r->>'recovery_min_gap_h')::numeric * interval '1 hour') then
      rec_left := rec_left - 1;
      rec_day := day_utc;
      rec_since := t;
    end if;
  else
    if was_age_h >= (r->>'rescue_from_h')::numeric then rescue := true; end if;
    -- check-up complete: no need is overdue any more
    if rescue and extract(epoch from (t - new_oldest)) / 3600 < (r->>'neglected_h')::numeric then
      rescue := false;
      rec_left := (r->>'recovery_days')::smallint;
      rec_day := day_utc;
      rec_since := t;
    end if;
  end if;

  -- good care day (PR A2): at most one per UTC day, never taken back. It needs enough different kinds of
  -- care that day and, right after this action, every need at good_day_min_need or more (or, only with the
  -- proposal knob good_day_cared_counts, cared for that day).
  kinds := (case when l.action_day_utc = day_utc then l.day_kinds else 0 end)
           | (case p_action when 'feed' then 1 when 'clean' then 2 when 'play' then 4 else 8 end);
  mn := (r->>'good_day_min_need')::numeric;
  cared := (r->>'good_day_cared_counts')::boolean;
  g_days := l.good_days; g_last := l.last_good_day_utc; g_streak := l.good_streak; g_best := l.best_good_streak;
  if l.last_good_day_utc is distinct from day_utc
     and (kinds & 1) + ((kinds >> 1) & 1) + ((kinds >> 2) & 1) + ((kinds >> 3) & 1)
         >= (r->>'good_day_min_kinds')::integer
     and (h >= mn or (cared and (kinds & 1) <> 0))
     and (c >= mn or (cared and (kinds & 2) <> 0))
     and (m >= mn or (cared and (kinds & 4) <> 0))
     and (en >= mn or (cared and (kinds & 8) <> 0)) then
    good_now := true;
    g_days := g_days + 1;
    g_streak := case when l.last_good_day_utc = day_utc - 1 then l.good_streak + 1 else 1 end;
    g_best := greatest(g_best, g_streak);
    g_last := day_utc;
  end if;

  update games.pepegochi_lives set
    hunger = h, hygiene = c, mood = m, energy = en, needs_at = t,
    hunger_due_at = due_h, hygiene_due_at = due_c, mood_due_at = due_m, energy_due_at = due_e,
    last_action_at = t,
    last_feed_at  = case when p_action = 'feed'  then t else last_feed_at end,
    last_clean_at = case when p_action = 'clean' then t else last_clean_at end,
    last_play_at  = case when p_action = 'play'  then t else last_play_at end,
    last_rest_at  = case when p_action = 'rest'  then t else last_rest_at end,
    feeds  = feeds  + case when p_action = 'feed'  then 1 else 0 end,
    cleans = cleans + case when p_action = 'clean' then 1 else 0 end,
    plays  = plays  + case when p_action = 'play'  then 1 else 0 end,
    rests  = rests  + case when p_action = 'rest'  then 1 else 0 end,
    action_day_utc = day_utc,
    actions_today = today_count + 1,
    care_days = care_days + case when new_care_day then 1 else 0 end,
    last_care_day_utc = day_utc,
    rescue_pending = rescue,
    recovery_days_left = rec_left,
    recovery_day_utc = rec_day,
    recovery_since = rec_since,
    day_kinds = kinds,
    good_days = g_days,
    last_good_day_utc = g_last,
    good_streak = g_streak,
    best_good_streak = g_best
  where life_id = l.life_id
  returning * into strict l;

  if new_care_day then
    -- the first accepted care hatches the egg
    if l.care_days = 1 then
      perform games.pepegochi_milestone(u, 'hatched', l.life_id, t);
    end if;
    if l.care_days >= (r->>'froglet_care_days')::integer then
      perform games.pepegochi_milestone(u, 'froglet', l.life_id, t);
    end if;
    if l.care_days >= (r->>'adult_care_days')::integer then
      perform games.pepegochi_milestone(u, 'adult', l.life_id, t);
    end if;
  end if;
  -- Good Parent foundation: good_parent_days good days in this one life. A milestone only; the stamp
  -- itself comes with the Passport bridge.
  if good_now and l.good_days >= (r->>'good_parent_days')::integer then
    perform games.pepegochi_milestone(u, 'good_parent', l.life_id, t);
  end if;
  perform games.pepegochi_sync(u);
  return games.pepegochi_view(u, t) || jsonb_build_object('action_result', 'accepted');
end
$$;
revoke all on function public.gry_pepegochi_action(text) from public, anon, authenticated;
grant execute on function public.gry_pepegochi_action(text) to authenticated;

-- Opens GOODBYE.TXT: writes the move-out if it is due, then marks the letter as read (once).
-- After this the owner can adopt a new egg. Safe to repeat.
create or replace function public.gry_pepegochi_letter_read()
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare
  u uuid := auth.uid();
  r jsonb := games.pepegochi_rules();
  t timestamptz;
  l games.pepegochi_lives%rowtype;
  has_owner boolean;
  had_life boolean;
begin
  if u is null or games.discord_identity(u) is null then
    raise exception 'Discord sign-in required' using errcode = '42501';
  end if;
  select true into has_owner from games.pepegochi_owners o where o.user_id = u for update;
  if has_owner is null then
    return games.pepegochi_view(u, games.pepegochi_clock());
  end if;
  select * into l from games.pepegochi_lives x where x.user_id = u
    order by x.generation desc limit 1 for update;
  had_life := found;
  t := games.pepegochi_clock();   -- after the locks
  if had_life then
    if l.status = 'active' and games.pepegochi_settle(l, t, r) then
      select * into strict l from games.pepegochi_lives x where x.life_id = l.life_id;
    end if;
    if l.status = 'departed' and l.letter_seen_at is null then
      update games.pepegochi_lives set letter_seen_at = t where life_id = l.life_id;
    end if;
  end if;
  return games.pepegochi_view(u, t);
end
$$;
revoke all on function public.gry_pepegochi_letter_read() from public, anon, authenticated;
grant execute on function public.gry_pepegochi_letter_read() to authenticated;

-- ====================================================================================================
-- 14/17  update_pepegochi_passport.sql
-- ====================================================================================================
-- PepeGochi v2 → Fren Passport bridge (PR C). DRAFT: not installed anywhere.
--
-- Run after, in this order: schema.sql, the Fren Passport files (update_fren_passport.sql,
-- update_fren_avatar.sql, update_passport_awards.sql) and update_pepegochi_v2.sql. Safe to run again.
--
-- What it does
--   * Replaces the no-op hook games.pepegochi_passport_sync(u) from update_pepegochi_v2.sql. The hook turns
--     the account milestones that PepeGochi records (games.pepegochi_milestones) into Passport stamps:
--       hatched        -> first_hatch   "First Hatch"      (the first care hatches the egg; owner, 2026-11-09)
--       froglet        -> little_fren   "Little Fren"      (2nd care day)
--       adult          -> grown_fren    "One Small Step"   (7th care day)
--       good_parent    -> good_parent   "Good Parent"      (good care days in one life)
--   * Every stamp goes through games.passport_award(): its allowlist, the Discord check and "once per account".
--     The stamp's date is the moment of the milestone, also when it is delivered later.
--   * Backfill: it delivers every milestone that is still pending when the file runs.
--
-- What it does not do
--   * Launch branch: the four stamps are live in the catalog and in passport_award()'s allowlist. A milestone
--     whose stamp is not allowed (an older Passport file) stays pending, silently, and is delivered later.
--   * first_adoption is recorded but is not a stamp (a new frog is an egg until its first care).
--   * certified_fren is never awarded by PepeGochi (it means 100 days of PondOS activity).
--   * It does not change gry_passport_state(), passport_award() or any Passport table.
--
-- Errors: "not in the allowlist" is the only error the hook catches itself. Anything else (a broken
-- Passport table, a failing trigger) reaches games.pepegochi_sync(), which logs a warning, keeps the care
-- action and leaves the milestone pending for the next accepted write.

do $$ begin
  if to_regclass('games.pepegochi_milestones') is null then
    raise exception 'Run update_pepegochi_v2.sql before update_pepegochi_passport.sql';
  end if;
  if to_regprocedure('games.passport_award(uuid, text, timestamp with time zone)') is null then
    raise exception 'Run update_passport_awards.sql before update_pepegochi_passport.sql';
  end if;
end $$;

-- milestone -> Passport stamp. null: not a stamp (yet).
create or replace function games.pepegochi_passport_stamp(m text)
returns text language sql immutable set search_path = '' as $$
  select case m
    when 'hatched' then 'first_hatch'
    when 'froglet' then 'little_fren'
    when 'adult' then 'grown_fren'
    when 'good_parent' then 'good_parent'
  end
$$;

-- Called by games.pepegochi_sync(u) inside the PepeGochi RPCs (as their owner), only while this account has
-- pending milestones. Same signature as the no-op in update_pepegochi_v2.sql, so create or replace works.
create or replace function games.pepegochi_passport_sync(u uuid)
returns void language plpgsql volatile set search_path = '' as $$
declare
  m record;
  s text;
begin
  for m in
    select ms.milestone, ms.reached_at from games.pepegochi_milestones ms
     where ms.user_id = u and ms.synced_at is null
     order by ms.reached_at, ms.milestone
       for update
  loop
    s := games.pepegochi_passport_stamp(m.milestone);
    if s is null then
      -- not a stamp (first_adoption): nothing to deliver, so it is done
      update games.pepegochi_milestones ms set synced_at = games.pepegochi_clock()
       where ms.user_id = u and ms.milestone = m.milestone;
      continue;
    end if;
    begin
      perform games.passport_award(u, s, m.reached_at);
    exception when raise_exception then
      -- "Unknown passport stamp": the Passport does not accept it yet (planned). It stays pending.
      -- Any other raised error is passed on.
      if sqlerrm not like 'Unknown passport stamp %' then raise; end if;
      continue;
    end;
    -- passport_award() answers false both for "had it already" and for "no Discord": the stamp row decides
    update games.pepegochi_milestones ms set synced_at = games.pepegochi_clock()
     where ms.user_id = u and ms.milestone = m.milestone
       and exists (select 1 from games.passport_badges b where b.user_id = u and b.badge_id = s);
  end loop;
end
$$;

revoke all on function games.pepegochi_passport_stamp(text), games.pepegochi_passport_sync(uuid)
  from public, anon, authenticated;

-- backfill: every account with a pending milestone (a no-op on an empty database, and while the stamps wait)
select games.pepegochi_passport_sync(x.user_id)
  from (select distinct user_id from games.pepegochi_milestones where synced_at is null) x;

-- ====================================================================================================
-- 15/17  update_pepegochi_room_v1.sql
-- ====================================================================================================
-- PepeGochi v2 Room-2 (DRAFT): account-owned inventory and room placements.
-- Dependency: games/supabase/update_pepegochi_v2.sql from PR #221 (A2).
-- Never apply to PH-games without explicit owner approval. Test on disposable PostgreSQL only.
-- This file does NOT award Moon Rock, real PEP, or anything earned in other games.
-- Browser roles cannot access tables, receive arbitrary gifts, or select another user.
-- No updates to PepeGochi lives, Passport, milestones, or departure logic.

-- Keep the backend's existing account and life tables authoritative.
do $$
begin
  if to_regclass('games.pepegochi_owners') is null
     or to_regclass('games.pepegochi_lives') is null
     or to_regprocedure('games.pepegochi_eval(games.pepegochi_lives,timestamp with time zone,jsonb)') is null then
    raise exception 'Install PepeGochi A1/A2 from PR #221 before Room-2';
  end if;
end $$;

-- Item definitions are internal allowlisted content, not a source of rewards by themselves.
create table if not exists games.pepegochi_room_catalog (
  item_id         text primary key check (item_id ~ '^[a-z][a-z0-9_]{2,49}$'),
  display_name    text not null check (char_length(display_name) between 1 and 80),
  category        text not null check (category in ('wall','small','trophy','lamp','electronics','large','plant','toy')),
  sprite_key      text not null check (sprite_key ~ '^[a-z][a-z0-9_]{2,63}$'),
  borrowable      boolean not null default false,
  active          boolean not null default true,
  is_starter      boolean not null default false,
  starter_slot_id text,
  check (not is_starter or starter_slot_id is not null)
);

create table if not exists games.pepegochi_room_slots (
  slot_id            text primary key check (slot_id ~ '^[a-z][a-z0-9_]{2,49}$'),
  label              text not null,
  x                  smallint not null check (x between 0 and 640),
  y                  smallint not null check (y between 0 and 400),
  z                  smallint not null check (z between 0 and 100),
  allowed_categories text[] not null check (coalesce(array_length(allowed_categories,1),0) between 1 and 8)
);

-- A single row per account tracks compare-and-swap edits across tabs.
create table if not exists games.pepegochi_room_revisions (
  user_id     uuid primary key references games.pepegochi_owners(user_id) on delete cascade,
  revision    bigint not null default 1 check (revision >= 1),
  updated_at  timestamptz not null default clock_timestamp()
);

-- Item instances belong to the ACCOUNT, not to a specific frog life.
-- source_key is a trusted server-defined idempotency key (not accepted from browser).
create table if not exists games.pepegochi_room_inventory (
  item_instance_id uuid primary key default gen_random_uuid(),
  user_id          uuid not null references games.pepegochi_owners(user_id) on delete cascade,
  item_id          text not null references games.pepegochi_room_catalog(item_id),
  source_key       text not null check (char_length(source_key) between 5 and 160),
  acquired_at      timestamptz not null default clock_timestamp(),
  unique (user_id, item_instance_id),
  unique (user_id, source_key)
);
create index if not exists pepegochi_room_inventory_owner
  on games.pepegochi_room_inventory (user_id, item_id);

create table if not exists games.pepegochi_room_placements (
  user_id          uuid not null references games.pepegochi_room_revisions(user_id) on delete cascade,
  slot_id          text not null references games.pepegochi_room_slots(slot_id),
  item_instance_id uuid not null,
  placed_at        timestamptz not null default clock_timestamp(),
  primary key (user_id, slot_id),
  unique (item_instance_id),
  foreign key (user_id, item_instance_id)
    references games.pepegochi_room_inventory(user_id, item_instance_id) on delete cascade
);

-- Defense in depth: even if someone grants usage of schema games later, the tables stay private.
alter table games.pepegochi_room_catalog enable row level security;
alter table games.pepegochi_room_slots enable row level security;
alter table games.pepegochi_room_revisions enable row level security;
alter table games.pepegochi_room_inventory enable row level security;
alter table games.pepegochi_room_placements enable row level security;
revoke all on games.pepegochi_room_catalog, games.pepegochi_room_slots,
  games.pepegochi_room_revisions, games.pepegochi_room_inventory,
  games.pepegochi_room_placements from public, anon, authenticated;

